// =========================================================
// APP
// =========================================================
// Áreas existentes no app e quais abas pertencem a cada uma.
// "usuarios" não é uma área — é liberada só pra quem é admin.
const AREA_DAS_ABAS = {
  rh: "ponto",
  comercial: "comercial",
};

export default function App() {
  const [session, setSession] = useState(null);
  const [tab, setTab] = useState(null);
  const [cargos, setCargos] = useState([]);
  const [funcionarios, setFuncionarios] = useState([]);
  const [lancamentos, setLancamentos] = useState([]);
  const [loading, setLoading] = useState(false);
  const [erro, setErro] = useState("");
  const [mesRef, setMesRef] = useState(() => {
    const d = new Date();
    return `${d.getFullYear()}-${MESES[d.getMonth()]}`;
  });

  const [perfil, setPerfil] = useState(null);
  const [areasPermitidas, setAreasPermitidas] = useState([]);
  const [carregandoAcesso, setCarregandoAcesso] = useState(false);

  const isAdmin = !!perfil?.is_admin;
  const temAcessoArea = (area) => isAdmin || areasPermitidas.includes(area);
  const podeVerAba = (abaId) => (abaId === "usuarios" ? isAdmin : temAcessoArea(AREA_DAS_ABAS[abaId]));

  // Carrega o perfil (nome, admin?) e as áreas liberadas pro usuário logado.
  useEffect(() => {
    if (!session?.user?.id) return;
    setCarregandoAcesso(true);
    Promise.all([
      sbRequest(`perfis?select=*&id=eq.${session.user.id}`, session),
      sbRequest(`usuarios_areas?select=area&user_id=eq.${session.user.id}`, session),
    ])
      .then(([p, ua]) => {
        setPerfil((p && p[0]) || null);
        setAreasPermitidas((ua || []).map((a) => a.area));
      })
      .catch((e) => setErro(e.message))
      .finally(() => setCarregandoAcesso(false));
  }, [session]); // eslint-disable-line

  // Assim que soubermos as permissões, manda pra primeira aba acessível.
  useEffect(() => {
    if (!session || carregandoAcesso || tab) return;
    if (podeVerAba("rh")) setTab("rh");
    else if (podeVerAba("comercial")) setTab("comercial");
    else if (podeVerAba("usuarios")) setTab("usuarios");
  }, [session, carregandoAcesso, perfil, areasPermitidas]); // eslint-disable-line

  useEffect(() => {
    if (!session || !temAcessoArea("ponto")) return;
    setLoading(true);
    setErro("");
    Promise.all([
      sbRequest("cargos?select=*&order=funcao.asc", session),
      sbRequest("funcionarios?select=*&order=nome.asc", session),
      sbRequest("lancamentos?select=*", session),
    ])
      .then(([c, f, l]) => {
        setCargos((c || []).map(cargoFromRow));
        setFuncionarios((f || []).map(funcionarioFromRow));
        setLancamentos((l || []).map(lancamentoFromRow));
      })
      .catch((e) => setErro(e.message))
      .finally(() => setLoading(false));
  }, [session, isAdmin, areasPermitidas]); // eslint-disable-line

  if (!session) {
    return <LoginScreen onLogin={setSession} />;
  }

  return (
    <div style={{ minHeight: "100vh", background: BG, color: TEXT, fontFamily: FONT_BODY }}>
      <Header tab={tab} setTab={setTab} onLogout={() => setSession(null)} podeVerAba={podeVerAba} />
      <main style={{ maxWidth: 1180, margin: "0 auto", padding: "28px 20px 80px" }}>
        {erro && (
          <div style={{ background: "#FDECEC", color: DANGER, padding: 12, borderRadius: 8, marginBottom: 16, fontSize: 13 }}>
            Erro ao falar com o Supabase: {erro}
          </div>
        )}
        {carregandoAcesso || (loading && temAcessoArea("ponto")) ? (
          <div style={{ display: "flex", alignItems: "center", gap: 8, color: MUTED }}>
            <Loader2 size={16} className="animate-spin" /> Carregando dados...
          </div>
        ) : !tab ? (
          <div style={{ color: MUTED }}>Seu usuário ainda não tem acesso a nenhuma área. Peça pra um administrador liberar na aba Usuários.</div>
        ) : !podeVerAba(tab) ? (
          <div style={{ color: MUTED }}>Você não tem acesso a essa área.</div>
        ) : (
          <>
            {tab === "rh" && (
              <RecursosHumanosView
                cargos={cargos} setCargos={setCargos}
                funcionarios={funcionarios} setFuncionarios={setFuncionarios}
                lancamentos={lancamentos} setLancamentos={setLancamentos}
                mesRef={mesRef} setMesRef={setMesRef}
                session={session} setErro={setErro}
              />
            )}
            {tab === "comercial" && (
              <ComercialView session={session} setErro={setErro} />
            )}
            {tab === "usuarios" && (
              <UsuariosView session={session} setErro={setErro} meuId={session?.user?.id} />
            )}
          </>
        )}
      </main>
    </div>
  );
}

// ---------- Login ----------
function LoginScreen({ onLogin }) {
  const [email, setEmail] = useState("");
  const [senha, setSenha] = useState("");
  const [erro, setErro] = useState("");
  const [carregando, setCarregando] = useState(false);

  async function handleSubmit(e) {
    e.preventDefault();
    setErro("");
    setCarregando(true);
    try {
      const data = await sbLogin(email, senha);
      onLogin(data);
    } catch (err) {
      setErro(err.message);
    } finally {
      setCarregando(false);
    }
  }

  return (
    <div style={{ minHeight: "100vh", background: NAVY, display: "flex", alignItems: "center", justifyContent: "center", fontFamily: FONT_BODY }}>
      <form onSubmit={handleSubmit} style={{ background: CARD, borderRadius: 14, padding: 32, width: 340, borderTop: `3px solid ${GOLD}` }}>
        <div style={{ fontFamily: FONT_MONO, fontSize: 11, letterSpacing: 2, color: GOLD, marginBottom: 4 }}>1385</div>
        <h1 style={{ margin: "0 0 22px", fontSize: 20, fontWeight: 700, color: NAVY }}>PROSIGN · Ponto</h1>
        {erro && <div style={{ background: "#FDECEC", color: DANGER, padding: 10, borderRadius: 8, fontSize: 13, marginBottom: 14 }}>{erro}</div>}
        <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
          <label style={{ fontSize: 12, color: MUTED }}>
            E-mail
            <input type="email" required value={email} onChange={(e) => setEmail(e.target.value)} style={{ ...inputStyle, width: "100%", marginTop: 5, boxSizing: "border-box" }} />
          </label>
          <label style={{ fontSize: 12, color: MUTED }}>
            Senha
            <input type="password" required value={senha} onChange={(e) => setSenha(e.target.value)} style={{ ...inputStyle, width: "100%", marginTop: 5, boxSizing: "border-box" }} />
          </label>
        </div>
        <button type="submit" disabled={carregando} style={{ ...btnPrimary, width: "100%", justifyContent: "center", marginTop: 20 }}>
          {carregando ? "Entrando..." : "Entrar"}
        </button>
        <div style={{ fontSize: 11, color: MUTED, marginTop: 14, textAlign: "center" }}>
          Usuários são criados no painel do Supabase (Authentication → Users).
        </div>
      </form>
    </div>
  );
}

// ---------- Header ----------
function Header({ tab, setTab, onLogout, podeVerAba }) {
  const items = [
    { id: "rh", label: "Recursos Humanos", icon: Users },
    { id: "comercial", label: "Comercial", icon: TrendingUp },
    { id: "usuarios", label: "Usuários", icon: UserCog },
  ].filter((it) => podeVerAba(it.id));
  return (
    <header style={{ background: NAVY, borderBottom: `3px solid ${GOLD}` }}>
      <div style={{ maxWidth: 1180, margin: "0 auto", padding: "18px 20px 0" }}>
        <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 16 }}>
          <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
            <img src={LOGO_PSVIEW} alt="PSView" style={{ height: 30, width: "auto" }} />
            <div style={{ display: "flex", alignItems: "baseline", gap: 10 }}>
              <span style={{ fontFamily: FONT_MONO, fontSize: 12, letterSpacing: 2, color: GOLD }}>1385</span>
              <h1 style={{ margin: 0, fontSize: 22, fontWeight: 700, color: "#fff", letterSpacing: 0.3 }}>
                PROSIGN <span style={{ fontWeight: 400, color: "#C7CEDB" }}>· Controle de Ponto</span>
              </h1>
            </div>
          </div>
          <button onClick={onLogout} style={{ display: "flex", alignItems: "center", gap: 6, background: "none", border: "none", color: "#C7CEDB", cursor: "pointer", fontSize: 13 }}>
            <LogOut size={15} /> Sair
          </button>
        </div>
        <nav style={{ display: "flex", gap: 4 }}>
          {items.map((it) => {
            const Icon = it.icon;
            const active = tab === it.id;
            return (
              <button
                key={it.id}
                onClick={() => setTab(it.id)}
                style={{
                  display: "flex", alignItems: "center", gap: 8,
                  padding: "10px 18px", border: "none", cursor: "pointer",
                  background: active ? BG : "transparent",
                  color: active ? NAVY : "#C7CEDB",
                  borderRadius: "8px 8px 0 0",
                  fontFamily: FONT_BODY, fontSize: 14, fontWeight: active ? 600 : 500,
                }}
              >
                <Icon size={16} /> {it.label}
              </button>
            );
          })}
        </nav>
      </div>
    </header>
  );
}

// =========================================================
// Recursos Humanos — agrupa Cargos e Salários, Funcionários,
// Lançamentos, Relatórios e Consulta numa única aba com sub-abas.
// =========================================================
function RecursosHumanosView({
  cargos, setCargos,
  funcionarios, setFuncionarios,
  lancamentos, setLancamentos,
  mesRef, setMesRef,
  session, setErro,
}) {
  const [subtab, setSubtab] = useState("cargos");

  const SUBABAS = [
    { id: "cargos", label: "Cargos e Salários" },
    { id: "funcionarios", label: "Funcionários" },
    { id: "lancamentos", label: "Lançamentos" },
    { id: "relatorios", label: "Relatórios" },
    { id: "consulta", label: "Consulta" },
  ];

  return (
    <div>
      <h2 style={{ margin: "0 0 18px", fontSize: 18, fontWeight: 700 }}>Recursos Humanos</h2>
      <div style={{ display: "flex", gap: 6, marginBottom: 18, flexWrap: "wrap" }}>
        {SUBABAS.map((s) => (
          <button
            key={s.id}
            onClick={() => setSubtab(s.id)}
            style={{
              padding: "8px 16px", borderRadius: 8, border: `1px solid ${subtab === s.id ? GOLD : BORDER}`,
              background: subtab === s.id ? GOLD : "#fff", color: subtab === s.id ? "#fff" : TEXT,
              fontSize: 13, fontWeight: 600, cursor: "pointer",
            }}
          >
            {s.label}
          </button>
        ))}
      </div>

      {subtab === "cargos" && (
        <CargosView cargos={cargos} setCargos={setCargos} session={session} setErro={setErro} />
      )}
      {subtab === "funcionarios" && (
        <FuncionariosView funcionarios={funcionarios} setFuncionarios={setFuncionarios} cargos={cargos} session={session} setErro={setErro} />
      )}
      {subtab === "lancamentos" && (
        <LancamentosView
          funcionarios={funcionarios} cargos={cargos}
          lancamentos={lancamentos} setLancamentos={setLancamentos}
          mesRef={mesRef} setMesRef={setMesRef}
          session={session} setErro={setErro}
        />
      )}
      {subtab === "relatorios" && (
        <RelatoriosView funcionarios={funcionarios} cargos={cargos} lancamentos={lancamentos} mesRef={mesRef} setMesRef={setMesRef} session={session} setErro={setErro} />
      )}
      {subtab === "consulta" && (
        <ConsultaView funcionarios={funcionarios} cargos={cargos} session={session} setErro={setErro} />
      )}
    </div>
  );
}

function Card({ children, style }) {
  return <div style={{ background: CARD, border: `1px solid ${BORDER}`, borderRadius: 12, padding: 22, ...style }}>{children}</div>;
}

function MesPicker({ mesRef, setMesRef }) {
  const [ano, mes] = mesRef.split("-");
  return (
    <div style={{ display: "flex", gap: 8, alignItems: "center" }}>
      <select value={mes} onChange={(e) => setMesRef(`${ano}-${e.target.value}`)} style={selStyle}>
        {MESES.map((m, i) => <option key={m} value={m}>{["Jan","Fev","Mar","Abr","Mai","Jun","Jul","Ago","Set","Out","Nov","Dez"][i]}</option>)}
      </select>
      <select value={ano} onChange={(e) => setMesRef(`${e.target.value}-${mes}`)} style={selStyle}>
        {[2024,2025,2026,2027].map((a) => <option key={a} value={a}>{a}</option>)}
      </select>
    </div>
  );
}

function Field({ label, children }) {
  return (
    <label style={{ display: "flex", flexDirection: "column", gap: 5, fontSize: 12, color: MUTED }}>
      {label}
      {children}
    </label>
  );
}

// =========================================================
// Cargos e Salários
// =========================================================
function CargosView({ cargos, setCargos, session, setErro }) {
  const [editing, setEditing] = useState(null);
  const [showForm, setShowForm] = useState(false);
  const [salvando, setSalvando] = useState(false);

  async function handleSave(c) {
    setSalvando(true);
    setErro("");
    try {
      if (c.id) {
        const [row] = await sbRequest(`cargos?id=eq.${c.id}`, session, { method: "PATCH", body: cargoToRow(c) });
        setCargos(cargos.map((x) => (x.id === c.id ? cargoFromRow(row) : x)));
      } else {
        const [row] = await sbRequest("cargos", session, { method: "POST", body: cargoToRow(c) });
        setCargos([...cargos, cargoFromRow(row)]);
      }
      setShowForm(false);
      setEditing(null);
    } catch (e) { setErro(e.message); }
    finally { setSalvando(false); }
  }
  async function handleDelete(id) {
    try {
      await sbRequest(`cargos?id=eq.${id}`, session, { method: "DELETE" });
      setCargos(cargos.filter((x) => x.id !== id));
    } catch (e) { setErro(e.message); }
  }

  return (
    <div>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 18 }}>
        <h2 style={{ margin: 0, fontSize: 18, fontWeight: 700 }}>Cargos e Salários ({cargos.length})</h2>
        <button onClick={() => { setEditing(null); setShowForm(true); }} style={btnPrimary}><Plus size={16} /> Novo cargo</button>
      </div>

      {showForm && <CargoForm initial={editing} onCancel={() => { setShowForm(false); setEditing(null); }} onSave={handleSave} salvando={salvando} />}

      <Card style={{ padding: 0, overflow: "hidden", marginTop: 18 }}>
        <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 13 }}>
          <thead>
            <tr style={{ background: "#F0F2F6", textAlign: "left" }}>
              {["Função", "CBO", "Salário-base", ""].map((h) => (
                <th key={h} style={{ padding: "10px 14px", fontWeight: 600, color: MUTED, fontSize: 11, textTransform: "uppercase", letterSpacing: 0.4 }}>{h}</th>
              ))}
            </tr>
          </thead>
          <tbody>
            {cargos.map((c) => (
              <tr key={c.id} style={{ borderTop: `1px solid ${BORDER}` }}>
                <td style={{ padding: "10px 14px", fontWeight: 600 }}>{c.funcao}</td>
                <td style={{ padding: "10px 14px", fontFamily: FONT_MONO, color: MUTED }}>{c.cbo}</td>
                <td style={{ padding: "10px 14px", fontFamily: FONT_MONO }}>{brl(c.salario)}</td>
                <td style={{ padding: "10px 14px", textAlign: "right" }}>
                  <button onClick={() => { setEditing(c); setShowForm(true); }} style={btnGhostSmall}>Editar</button>{" "}
                  <button onClick={() => handleDelete(c.id)} style={btnDangerSmall}><Trash2 size={13} /></button>
                </td>
              </tr>
            ))}
            {cargos.length === 0 && <tr><td colSpan={4} style={{ padding: 20, color: MUTED, textAlign: "center" }}>Nenhum cargo cadastrado ainda.</td></tr>}
          </tbody>
        </table>
      </Card>
    </div>
  );
}

function CargoForm({ initial, onCancel, onSave, salvando }) {
  const [c, setC] = useState(initial || { funcao: "", cbo: "", salario: "" });
  return (
    <Card style={{ marginBottom: 8 }}>
      <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 16 }}>
        <h3 style={{ margin: 0, fontSize: 15 }}>{initial ? "Editar cargo" : "Novo cargo"}</h3>
        <button onClick={onCancel} style={{ background: "none", border: "none", cursor: "pointer", color: MUTED }}><X size={18} /></button>
      </div>
      <div style={{ display: "grid", gridTemplateColumns: "2fr 1fr 1fr", gap: 12 }}>
        <Field label="Função"><input style={inputStyle} value={c.funcao} onChange={(e) => setC({ ...c, funcao: e.target.value })} /></Field>
        <Field label="Código CBO"><input style={inputStyle} placeholder="0000-00" value={c.cbo} onChange={(e) => setC({ ...c, cbo: e.target.value })} /></Field>
        <Field label="Salário-base (R$)"><input type="number" step="0.01" style={inputStyle} value={c.salario} onChange={(e) => setC({ ...c, salario: parseFloat(e.target.value) || 0 })} /></Field>
      </div>
      <div style={{ display: "flex", justifyContent: "flex-end", gap: 8, marginTop: 18 }}>
        <button onClick={onCancel} style={btnGhostSmall}>Cancelar</button>
        <button onClick={() => onSave(c)} disabled={salvando} style={btnPrimary}><Save size={15} /> {salvando ? "Salvando..." : "Salvar"}</button>
      </div>
    </Card>
  );
}

// =========================================================
// Funcionários
// =========================================================
function FuncionariosView({ funcionarios, setFuncionarios, cargos, session, setErro }) {
  const [editing, setEditing] = useState(null);
  const [showForm, setShowForm] = useState(false);
  const [salvando, setSalvando] = useState(false);

  async function handleSave(f) {
    setSalvando(true);
    setErro("");
    try {
      let fotoUrl = f.fotoUrl;
      if (f.fotoFile) {
        const ext = f.fotoFile.name.split(".").pop();
        const path = `${f.codigo || Date.now()}-${Date.now()}.${ext}`;
        fotoUrl = await sbUploadFoto(f.fotoFile, path, session);
      }
      const payload = funcionarioToRow({ ...f, fotoUrl });
      if (f.id) {
        const [row] = await sbRequest(`funcionarios?id=eq.${f.id}`, session, { method: "PATCH", body: payload });
        setFuncionarios(funcionarios.map((x) => (x.id === f.id ? funcionarioFromRow(row) : x)));
      } else {
        const [row] = await sbRequest("funcionarios", session, { method: "POST", body: payload });
        setFuncionarios([...funcionarios, funcionarioFromRow(row)]);
      }
      setShowForm(false);
      setEditing(null);
    } catch (e) { setErro(e.message); }
    finally { setSalvando(false); }
  }
  async function handleDelete(id) {
    try {
      await sbRequest(`funcionarios?id=eq.${id}`, session, { method: "DELETE" });
      setFuncionarios(funcionarios.filter((x) => x.id !== id));
    } catch (e) { setErro(e.message); }
  }

  return (
    <div>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 18 }}>
        <h2 style={{ margin: 0, fontSize: 18, fontWeight: 700 }}>Funcionários ({funcionarios.length})</h2>
        <button onClick={() => { setEditing(null); setShowForm(true); }} style={btnPrimary}><Plus size={16} /> Novo funcionário</button>
      </div>

      {showForm && (
        <FuncionarioForm initial={editing} cargos={cargos} onCancel={() => { setShowForm(false); setEditing(null); }} onSave={handleSave} salvando={salvando} />
      )}

      {!showForm && cargos.length === 0 && (
        <div style={{ color: MUTED, fontSize: 13, marginBottom: 14 }}>Cadastre ao menos um cargo em "Cargos e Salários" antes de adicionar funcionários.</div>
      )}

      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(220px, 1fr))", gap: 14, marginTop: 18 }}>
        {funcionarios.map((f) => {
          const cargo = cargos.find((c) => c.id === f.cargoId);
          const salarioTotal = (cargo?.salario || 0) + (f.gratificacao || 0);
          return (
            <Card key={f.id} style={{ padding: 16 }}>
              <div style={{ display: "flex", gap: 12, alignItems: "center" }}>
                <div style={{ width: 52, height: 52, borderRadius: "50%", overflow: "hidden", background: "#EEF1F5", flexShrink: 0, display: "flex", alignItems: "center", justifyContent: "center", border: `2px solid ${BORDER}` }}>
                  {f.fotoUrl ? <img src={f.fotoUrl} alt={f.nome} style={{ width: "100%", height: "100%", objectFit: "cover" }} /> : <Users size={22} color={MUTED} />}
                </div>
                <div style={{ minWidth: 0 }}>
                  <div style={{ fontWeight: 700, fontSize: 14, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{f.nome}</div>
                  <div style={{ fontSize: 12, color: MUTED }}>{f.codigo} · {cargo?.funcao || "sem cargo"}</div>
                </div>
              </div>
              <div style={{ marginTop: 10, fontSize: 12, color: MUTED, fontFamily: FONT_MONO }}>
                Admissão {f.admissao} · {brl(salarioTotal)}
                {f.gratificacao > 0 && <span style={{ color: GOLD }}> (+{brl(f.gratificacao)} grat.)</span>}
              </div>
              <div style={{ display: "flex", gap: 8, marginTop: 12 }}>
                <button onClick={() => { setEditing(f); setShowForm(true); }} style={btnGhostSmall}>Editar</button>
                <button onClick={() => handleDelete(f.id)} style={btnDangerSmall}><Trash2 size={13} /></button>
              </div>
            </Card>
          );
        })}
        {funcionarios.length === 0 && <div style={{ color: MUTED, fontSize: 14 }}>Nenhum funcionário cadastrado ainda.</div>}
      </div>
    </div>
  );
}

function FuncionarioForm({ initial, onCancel, onSave, cargos, salvando }) {
  const [f, setF] = useState(initial || { codigo: "", nome: "", cargoId: cargos[0]?.id || "", gratificacao: 0, admissao: "", fotoUrl: "" });
  const [preview, setPreview] = useState(initial?.fotoUrl || "");
  const fileRef = useRef();

  function handleFoto(e) {
    const file = e.target.files?.[0];
    if (!file) return;
    setF((s) => ({ ...s, fotoFile: file }));
    setPreview(URL.createObjectURL(file));
  }

  return (
    <Card style={{ marginBottom: 8 }}>
      <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 16 }}>
        <h3 style={{ margin: 0, fontSize: 15 }}>{initial ? "Editar funcionário" : "Novo funcionário"}</h3>
        <button onClick={onCancel} style={{ background: "none", border: "none", cursor: "pointer", color: MUTED }}><X size={18} /></button>
      </div>
      <div style={{ display: "flex", gap: 20 }}>
        <div style={{ flexShrink: 0 }}>
          <div onClick={() => fileRef.current.click()} style={{ width: 96, height: 96, borderRadius: "50%", background: "#EEF1F5", cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center", overflow: "hidden", border: `2px dashed ${BORDER}` }}>
            {preview ? <img src={preview} alt="" style={{ width: "100%", height: "100%", objectFit: "cover" }} /> : <Upload size={22} color={MUTED} />}
          </div>
          <input type="file" accept="image/*" ref={fileRef} onChange={handleFoto} style={{ display: "none" }} />
          <div style={{ fontSize: 11, color: MUTED, textAlign: "center", marginTop: 6 }}>Foto</div>
        </div>
        <div style={{ flex: 1, display: "grid", gridTemplateColumns: "1fr 1fr", gap: 12 }}>
          <Field label="Código"><input style={inputStyle} value={f.codigo} onChange={(e) => setF({ ...f, codigo: e.target.value })} /></Field>
          <Field label="Nome completo"><input style={inputStyle} value={f.nome} onChange={(e) => setF({ ...f, nome: e.target.value })} /></Field>
          <Field label="Cargo">
            <select style={inputStyle} value={f.cargoId} onChange={(e) => setF({ ...f, cargoId: e.target.value })}>
              <option value="">Selecione...</option>
              {cargos.map((c) => <option key={c.id} value={c.id}>{c.funcao} ({brl(c.salario)})</option>)}
            </select>
          </Field>
          <Field label="Admissão"><input type="date" style={inputStyle} value={f.admissao} onChange={(e) => setF({ ...f, admissao: e.target.value })} /></Field>
          <Field label="Gratificação (R$)"><input type="number" step="0.01" style={inputStyle} value={f.gratificacao} onChange={(e) => setF({ ...f, gratificacao: parseFloat(e.target.value) || 0 })} /></Field>
        </div>
      </div>
      <div style={{ display: "flex", justifyContent: "flex-end", gap: 8, marginTop: 18 }}>
        <button onClick={onCancel} style={btnGhostSmall}>Cancelar</button>
        <button onClick={() => onSave(f)} disabled={salvando} style={btnPrimary}><Save size={15} /> {salvando ? "Salvando..." : "Salvar"}</button>
      </div>
    </Card>
  );
}

// =========================================================
// Lançamentos — bate ponto diário + faltas/DSR/atestado mensal
// =========================================================
function LancamentosView({ funcionarios, cargos, lancamentos, setLancamentos, mesRef, setMesRef, session, setErro }) {
  const [selId, setSelId] = useState(funcionarios[0]?.id || "");
  const [registros, setRegistros] = useState([]);
  const [carregandoRegistros, setCarregandoRegistros] = useState(false);
  const [salvandoPonto, setSalvandoPonto] = useState(false);
  const [salvandoFaltas, setSalvandoFaltas] = useState(false);
  const funcionario = funcionarios.find((f) => String(f.id) === String(selId));

  const blankPonto = {
    data: `${mesRef}-01`, entrada: "", saida: "", feriado: false,
    temAlmoco: false, almocoHoras: 0,
    mostrarTurno2: false, entrada2: "", saida2: "",
    mostrarTurno3: false, entrada3: "", saida3: "",
    observacao: "",
  };
  const [pontoForm, setPontoForm] = useState(blankPonto);

  const blankFaltas = { funcionarioId: selId, mes: mesRef, faltasDias: 0, faltasHoras: 0, dsrDias: 0, atestadoDias: 0 };
  const [faltasForm, setFaltasForm] = useState(blankFaltas);

  useEffect(() => {
    const ex = lancamentos.find((l) => String(l.funcionarioId) === String(selId) && l.mes === mesRef);
    setFaltasForm(ex || { ...blankFaltas, funcionarioId: selId, mes: mesRef });
    setPontoForm({ ...blankPonto, data: `${mesRef}-01` });
  }, [selId, mesRef]); // eslint-disable-line

  useEffect(() => {
    if (!selId) return;
    const { inicio, fimExclusivo } = mesRange(mesRef);
    setCarregandoRegistros(true);
    sbRequest(`registros_ponto?select=*&funcionario_id=eq.${selId}&data=gte.${inicio}&data=lt.${fimExclusivo}&order=data.asc`, session)
      .then((rows) => setRegistros((rows || []).map(registroFromRow)))
      .catch((e) => setErro(e.message))
      .finally(() => setCarregandoRegistros(false));
  }, [selId, mesRef, session]); // eslint-disable-line

  async function handleSalvarPonto() {
    if (!pontoForm.data || !pontoForm.entrada || !pontoForm.saida) return;
    setSalvandoPonto(true);
    setErro("");
    try {
      const almocoHoras = pontoForm.temAlmoco ? pontoForm.almocoHoras : 0;
      const entrada2 = pontoForm.mostrarTurno2 ? pontoForm.entrada2 : "";
      const saida2 = pontoForm.mostrarTurno2 ? pontoForm.saida2 : "";
      const entrada3 = pontoForm.mostrarTurno2 && pontoForm.mostrarTurno3 ? pontoForm.entrada3 : "";
      const saida3 = pontoForm.mostrarTurno2 && pontoForm.mostrarTurno3 ? pontoForm.saida3 : "";
      const row = registroToRow({ ...pontoForm, almocoHoras, entrada2, saida2, entrada3, saida3, funcionarioId: selId });
      const [saved] = await sbRequest("registros_ponto?on_conflict=funcionario_id,data", session, {
        method: "POST", body: row, extraHeaders: { Prefer: "resolution=merge-duplicates,return=representation" },
      });
      const novo = registroFromRow(saved);
      setRegistros((rs) => {
        const next = rs.some((r) => r.id === novo.id) ? rs.map((r) => (r.id === novo.id ? novo : r)) : [...rs, novo];
        return next.sort((a, b) => a.data.localeCompare(b.data));
      });
      setPontoForm({ ...blankPonto, data: pontoForm.data });
    } catch (e) { setErro(e.message); }
    finally { setSalvandoPonto(false); }
  }

  async function handleExcluirPonto(id) {
    try {
      await sbRequest(`registros_ponto?id=eq.${id}`, session, { method: "DELETE" });
      setRegistros((rs) => rs.filter((r) => r.id !== id));
    } catch (e) { setErro(e.message); }
  }

  async function handleSalvarFaltas() {
    setSalvandoFaltas(true);
    setErro("");
    try {
      const row = lancamentoToRow(faltasForm);
      const [saved] = await sbRequest("lancamentos?on_conflict=funcionario_id,mes_referencia", session, {
        method: "POST", body: row, extraHeaders: { Prefer: "resolution=merge-duplicates,return=representation" },
      });
      const novo = lancamentoFromRow(saved);
      const next = lancamentos.some((l) => l.id === novo.id)
        ? lancamentos.map((l) => (l.id === novo.id ? novo : l))
        : [...lancamentos.filter((l) => !(String(l.funcionarioId) === String(selId) && l.mes === mesRef)), novo];
      setLancamentos(next);
      setFaltasForm(novo);
    } catch (e) { setErro(e.message); }
    finally { setSalvandoFaltas(false); }
  }

  async function handleExcluirFaltas() {
    const existente = lancamentos.find((l) => String(l.funcionarioId) === String(selId) && l.mes === mesRef);
    if (!existente) {
      // nada salvo no banco ainda, só limpa o formulário
      setFaltasForm({ ...blankFaltas, funcionarioId: selId, mes: mesRef });
      return;
    }
    if (!window.confirm("Excluir faltas/DSR/atestado deste funcionário neste mês?")) return;
    setSalvandoFaltas(true);
    setErro("");
    try {
      await sbRequest(`lancamentos?id=eq.${existente.id}`, session, { method: "DELETE" });
      setLancamentos(lancamentos.filter((l) => l.id !== existente.id));
      setFaltasForm({ ...blankFaltas, funcionarioId: selId, mes: mesRef });
    } catch (e) { setErro(e.message); }
    finally { setSalvandoFaltas(false); }
  }

  if (!funcionarios.length) return <div style={{ color: MUTED }}>Cadastre um funcionário primeiro na aba "Funcionários".</div>;

  const agregado = agregarMes(registros);
  const lancParaCalculo = { ...agregado, faltasDias: faltasForm.faltasDias, faltasHoras: faltasForm.faltasHoras, dsrDias: faltasForm.dsrDias };
  const preview = funcionario ? calcularLancamento(funcionario, cargos, lancParaCalculo) : null;
  const pontoFormSemHorarioFixo = !diaTemHorarioFixo(pontoForm.data, pontoForm.feriado);

  return (
    <div>
      <div style={{ display: "flex", gap: 12, marginBottom: 18, flexWrap: "wrap", alignItems: "center" }}>
        <select value={selId} onChange={(e) => setSelId(e.target.value)} style={{ ...selStyle, minWidth: 240 }}>
          {funcionarios.map((f) => <option key={f.id} value={f.id}>{f.codigo} — {f.nome}</option>)}
        </select>
        <MesPicker mesRef={mesRef} setMesRef={setMesRef} />
      </div>

      <div style={{ display: "grid", gridTemplateColumns: "1.3fr 1fr", gap: 18 }}>
        <div style={{ display: "flex", flexDirection: "column", gap: 18 }}>
          <Card>
            <h3 style={{ marginTop: 0, fontSize: 14, color: MUTED, fontWeight: 600, textTransform: "uppercase", letterSpacing: 0.5 }}>Bater ponto do dia</h3>
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr auto", gap: 10, alignItems: "end" }}>
              <Field label="Data">
                <input type="date" style={inputStyle} value={pontoForm.data} onChange={(e) => setPontoForm({ ...pontoForm, data: e.target.value })} />
              </Field>
              <Field label="Entrada">
                <input type="time" style={inputStyle} value={pontoForm.entrada} onChange={(e) => setPontoForm({ ...pontoForm, entrada: e.target.value })} />
              </Field>
              <Field label="Saída">
                <input type="time" style={inputStyle} value={pontoForm.saida} onChange={(e) => setPontoForm({ ...pontoForm, saida: e.target.value })} />
              </Field>
              <label style={{ display: "flex", alignItems: "center", gap: 6, fontSize: 12, color: MUTED, paddingBottom: 9 }}>
                <input type="checkbox" checked={pontoForm.feriado} onChange={(e) => setPontoForm({ ...pontoForm, feriado: e.target.checked })} />
                Feriado
              </label>
            </div>

            {pontoFormSemHorarioFixo && (
              <div style={{ display: "flex", gap: 14, alignItems: "end", marginTop: 12, padding: 12, background: "#FBF3E3", borderRadius: 8 }}>
                <label style={{ display: "flex", alignItems: "center", gap: 6, fontSize: 12, color: "#8A6A20" }}>
                  <input
                    type="checkbox"
                    checked={pontoForm.temAlmoco}
                    onChange={(e) => setPontoForm({ ...pontoForm, temAlmoco: e.target.checked, almocoHoras: e.target.checked ? (pontoForm.almocoHoras || 1) : 0 })}
                  />
                  Teve horário de almoço?
                </label>
                {pontoForm.temAlmoco && (
                  <Field label="Duração do almoço (hh:mm)">
                    <input
                      style={inputStyle}
                      placeholder="1:00"
                      defaultValue={decimalToHHMM(pontoForm.almocoHoras || 1)}
                      onBlur={(e) => setPontoForm((s) => ({ ...s, almocoHoras: hhmmToDecimal(e.target.value) }))}
                    />
                  </Field>
                )}
              </div>
            )}

            <div style={{ marginTop: 12 }}>
              {!pontoForm.mostrarTurno2 ? (
                <button type="button" onClick={() => setPontoForm({ ...pontoForm, mostrarTurno2: true })} style={btnGhostSmall}>
                  + Adicionar 2º turno (voltou depois de ir embora)
                </button>
              ) : (
                <div style={{ padding: 12, background: "#F0F2F6", borderRadius: 8 }}>
                  <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 8 }}>
                    <span style={{ fontSize: 12, fontWeight: 600, color: MUTED }}>2º turno</span>
                    <button
                      type="button"
                      onClick={() => setPontoForm({ ...pontoForm, mostrarTurno2: false, mostrarTurno3: false, entrada2: "", saida2: "", entrada3: "", saida3: "" })}
                      style={{ background: "none", border: "none", color: DANGER, cursor: "pointer", fontSize: 12 }}
                    >
                      Remover
                    </button>
                  </div>
                  <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10 }}>
                    <Field label="Entrada">
                      <input type="time" style={inputStyle} value={pontoForm.entrada2} onChange={(e) => setPontoForm({ ...pontoForm, entrada2: e.target.value })} />
                    </Field>
                    <Field label="Saída">
                      <input type="time" style={inputStyle} value={pontoForm.saida2} onChange={(e) => setPontoForm({ ...pontoForm, saida2: e.target.value })} />
                    </Field>
                  </div>

                  {!pontoForm.mostrarTurno3 ? (
                    <button type="button" onClick={() => setPontoForm({ ...pontoForm, mostrarTurno3: true })} style={{ ...btnGhostSmall, marginTop: 10 }}>
                      + Adicionar 3º turno
                    </button>
                  ) : (
                    <div style={{ marginTop: 10 }}>
                      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 8 }}>
                        <span style={{ fontSize: 12, fontWeight: 600, color: MUTED }}>3º turno</span>
                        <button
                          type="button"
                          onClick={() => setPontoForm({ ...pontoForm, mostrarTurno3: false, entrada3: "", saida3: "" })}
                          style={{ background: "none", border: "none", color: DANGER, cursor: "pointer", fontSize: 12 }}
                        >
                          Remover
                        </button>
                      </div>
                      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10 }}>
                        <Field label="Entrada">
                          <input type="time" style={inputStyle} value={pontoForm.entrada3} onChange={(e) => setPontoForm({ ...pontoForm, entrada3: e.target.value })} />
                        </Field>
                        <Field label="Saída">
                          <input type="time" style={inputStyle} value={pontoForm.saida3} onChange={(e) => setPontoForm({ ...pontoForm, saida3: e.target.value })} />
                        </Field>
                      </div>
                    </div>
                  )}
                </div>
              )}
            </div>

            <div style={{ marginTop: 12 }}>
              <Field label="Observação (motivo da hora extra, etc.)">
                <textarea
                  style={{ ...inputStyle, resize: "vertical", minHeight: 50, fontFamily: FONT_BODY, width: "100%", boxSizing: "border-box" }}
                  value={pontoForm.observacao}
                  onChange={(e) => setPontoForm({ ...pontoForm, observacao: e.target.value })}
                />
              </Field>
            </div>

            <button onClick={handleSalvarPonto} disabled={salvandoPonto} style={{ ...btnPrimary, marginTop: 14 }}>
              <Plus size={15} /> {salvandoPonto ? "Salvando..." : "Adicionar / atualizar dia"}
            </button>

            <div style={{ marginTop: 18, borderTop: `1px solid ${BORDER}`, paddingTop: 14 }}>
              {carregandoRegistros ? (
                <div style={{ fontSize: 13, color: MUTED }}>Carregando dias batidos...</div>
              ) : registros.length === 0 ? (
                <div style={{ fontSize: 13, color: MUTED }}>Nenhum dia registrado neste mês ainda.</div>
              ) : (
                <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 12 }}>
                  <thead>
                    <tr style={{ textAlign: "left", color: MUTED }}>
                      <th style={{ padding: "4px 6px" }}>Dia</th>
                      <th style={{ padding: "4px 6px" }}>Entrada</th>
                      <th style={{ padding: "4px 6px" }}>Saída</th>
                      <th style={{ padding: "4px 6px" }}>Classificação</th>
                      <th></th>
                    </tr>
                  </thead>
                  <tbody>
                    {registros.map((r) => {
                      const c = classificarDia(r);
                      const tags = Object.entries(c).filter(([k, v]) => k !== "normal" && v > 0);
                      return (
                        <tr key={r.id} style={{ borderTop: `1px solid ${BORDER}` }}>
                          <td style={{ padding: "6px" }}>
                            {r.data.slice(8,10)}/{r.data.slice(5,7)} · {diaSemanaLabel(r.data)}{r.feriado ? " 🎉" : ""}{r.almocoHoras > 0 ? ` 🍽️ ${decimalToHHMM(r.almocoHoras)}` : ""}
                            {r.observacao && <div style={{ fontSize: 10, color: MUTED, fontStyle: "italic", marginTop: 2, maxWidth: 140 }}>{r.observacao}</div>}
                          </td>
                          <td style={{ padding: "6px", fontFamily: FONT_MONO }}>
                            {r.entrada}
                            {r.entrada2 && <><br />{r.entrada2}</>}
                            {r.entrada3 && <><br />{r.entrada3}</>}
                          </td>
                          <td style={{ padding: "6px", fontFamily: FONT_MONO }}>
                            {r.saida}
                            {r.saida2 && <><br />{r.saida2}</>}
                            {r.saida3 && <><br />{r.saida3}</>}
                          </td>
                          <td style={{ padding: "6px" }}>
                            {tags.length === 0 ? <span style={{ color: MUTED }}>só horas normais</span> : tags.map(([k, v]) => (
                              <span key={k} style={{ marginRight: 8, color: BAR_COLORS[k] || MUTED }}>{CAMPOS_LANC.find((c2) => c2.key === k)?.label.replace("H. Extras ", "").replace("Adic. ", "") || k}: {decimalToHHMM(v)}</span>
                            ))}
                          </td>
                          <td style={{ padding: "6px", textAlign: "right" }}>
                            <button onClick={() => handleExcluirPonto(r.id)} style={{ background: "none", border: "none", color: DANGER, cursor: "pointer" }}><Trash2 size={13} /></button>
                          </td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              )}
            </div>
          </Card>

          <Card>
            <h3 style={{ marginTop: 0, fontSize: 14, color: MUTED, fontWeight: 600, textTransform: "uppercase", letterSpacing: 0.5 }}>Faltas / DSR / Atestado (mês)</h3>
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 12 }}>
              <Field label="Faltas não just. (dias)"><input type="number" style={inputStyle} value={faltasForm.faltasDias} onChange={(e) => setFaltasForm({ ...faltasForm, faltasDias: parseFloat(e.target.value) || 0 })} /></Field>
              <Field label="Faltas não just. (hh:mm)"><input style={inputStyle} placeholder="0:00" defaultValue={decimalToHHMM(faltasForm.faltasHoras)} onBlur={(e) => setFaltasForm((s) => ({ ...s, faltasHoras: hhmmToDecimal(e.target.value) }))} /></Field>
              <Field label="D.S.R. perdido (dias)"><input type="number" style={inputStyle} value={faltasForm.dsrDias} onChange={(e) => setFaltasForm({ ...faltasForm, dsrDias: parseFloat(e.target.value) || 0 })} /></Field>
              <Field label="Atestado (dias)"><input type="number" style={inputStyle} value={faltasForm.atestadoDias} onChange={(e) => setFaltasForm({ ...faltasForm, atestadoDias: parseFloat(e.target.value) || 0 })} /></Field>
            </div>
            <div style={{ display: "flex", gap: 8, marginTop: 14 }}>
              <button onClick={handleSalvarFaltas} disabled={salvandoFaltas} style={btnPrimary}><Save size={15} /> {salvandoFaltas ? "Salvando..." : "Salvar faltas/DSR"}</button>
              <button onClick={handleExcluirFaltas} disabled={salvandoFaltas} style={btnDangerSmall}><Trash2 size={13} /> Excluir lançamento do mês</button>
            </div>
          </Card>
        </div>

        {preview && (
          <Card style={{ background: NAVY, color: "#fff", height: "fit-content" }}>
            <div style={{ fontSize: 12, color: "#9FB0CC", textTransform: "uppercase", letterSpacing: 0.5 }}>Prévia do cálculo (mês)</div>
            <div style={{ fontSize: 13, color: "#C7CEDB", marginTop: 4, fontFamily: FONT_MONO }}>Base: {brl(preview.salario)} · Hora: {brl(preview.valorHora)}</div>
            <div style={{ fontSize: 12, color: "#9FB0CC", marginTop: 8 }}>Horas normais batidas: {decimalToHHMM(agregado.normal)}</div>
            <div style={{ marginTop: 14, display: "flex", flexDirection: "column", gap: 6 }}>
              {preview.linhas.filter((l) => l.horas > 0).map((l) => (
                <div key={l.key} style={{ display: "flex", justifyContent: "space-between", fontSize: 13 }}>
                  <span style={{ color: "#C7CEDB" }}>{l.label} {l.excedente > 0 && <span style={{ color: "#FFB86C" }}>({decimalToHHMM(l.dentro)} + {decimalToHHMM(l.excedente)} exced.)</span>}</span>
                  <span style={{ fontFamily: FONT_MONO, color: GOLD }}>{brl(l.valorDentro)}</span>
                </div>
              ))}
            </div>
            <div style={{ borderTop: "1px solid rgba(255,255,255,.15)", marginTop: 12, paddingTop: 12, display: "flex", justifyContent: "space-between", fontWeight: 700 }}>
              <span>Total extras (até 40h)</span><span style={{ fontFamily: FONT_MONO }}>{brl(preview.totalValorExtras)}</span>
            </div>
            {preview.totalHorasExcedentes > 0 && (
              <div style={{ display: "flex", justifyContent: "space-between", fontSize: 13, color: "#FFB86C", marginTop: 6 }}>
                <span>Pagamento de Extras (&gt;40h, {decimalToHHMM(preview.totalHorasExcedentes)})</span>
                <span style={{ fontFamily: FONT_MONO }}>{brl(preview.totalValorExcedentes)}</span>
              </div>
            )}
            {preview.totalDescontos > 0 && (
              <div style={{ display: "flex", justifyContent: "space-between", fontSize: 13, color: "#FF9DA8", marginTop: 6 }}>
                <span>Descontos (faltas/DSR)</span><span style={{ fontFamily: FONT_MONO }}>- {brl(preview.totalDescontos)}</span>
              </div>
            )}
            <div style={{ display: "flex", justifyContent: "space-between", marginTop: 10, fontSize: 15, fontWeight: 700, color: GOLD }}>
              <span>Líquido (extras + excedente &gt;40h)</span><span style={{ fontFamily: FONT_MONO }}>{brl(preview.liquido)}</span>
            </div>
          </Card>
        )}
      </div>
    </div>
  );
}

// =========================================================
// Relatórios
// =========================================================
function RelatoriosView({ funcionarios, cargos, lancamentos, mesRef, setMesRef, session, setErro }) {
  const [registrosMes, setRegistrosMes] = useState([]);
  const [carregando, setCarregando] = useState(false);
  const [filtro, setFiltro] = useState("tudo"); // 'tudo' | 'normais' | 'extras'
  const [funcSelId, setFuncSelId] = useState("todos");
  const [modo, setModo] = useState("resumo"); // 'resumo' | 'detalhado'

  useEffect(() => {
    const { inicio, fimExclusivo } = mesRange(mesRef);
    setCarregando(true);
    sbRequest(`registros_ponto?select=*&data=gte.${inicio}&data=lt.${fimExclusivo}`, session)
      .then((rows) => setRegistrosMes((rows || []).map(registroFromRow)))
      .catch((e) => setErro(e.message))
      .finally(() => setCarregando(false));
  }, [mesRef, session]); // eslint-disable-line

  const rowsTodas = useMemo(() => funcionarios.map((f) => {
    const lancFaltas = lancamentos.find((l) => String(l.funcionarioId) === String(f.id) && l.mes === mesRef) || {};
    const registrosFunc = registrosMes.filter((r) => r.funcionarioId === f.id);
    const agregado = agregarMes(registrosFunc);
    const lanc = { ...agregado, faltasDias: lancFaltas.faltasDias || 0, faltasHoras: lancFaltas.faltasHoras || 0, dsrDias: lancFaltas.dsrDias || 0 };
    const calc = calcularLancamento(f, cargos, lanc);
    const cargo = cargos.find((c) => c.id === f.cargoId);
    return { f, cargo, lanc, calc, horasNormais: agregado.normal };
  }), [funcionarios, cargos, lancamentos, registrosMes, mesRef]);

  const rows = useMemo(
    () => (funcSelId === "todos" ? rowsTodas : rowsTodas.filter((r) => String(r.f.id) === String(funcSelId))),
    [rowsTodas, funcSelId]
  );

  // Linhas dia a dia (para o modo "Detalhado") — mesma lógica da aba Consulta,
  // uma linha por dia batido de cada funcionário dentro do filtro selecionado.
  const linhasDetalhadas = useMemo(() => {
    const alvo = funcSelId === "todos" ? funcionarios : funcionarios.filter((f) => String(f.id) === String(funcSelId));
    const linhas = [];
    alvo.forEach((f) => {
      const valorHora = salarioBase(f, cargos) / DIVISOR_HORA;
      const registrosFunc = registrosMes.filter((r) => r.funcionarioId === f.id);
      registrosFunc.forEach((r) => {
        const c = classificarDia(r);
        linhas.push({ f, r, c, valorHora });
      });
    });
    linhas.sort((a, b) => a.r.data.localeCompare(b.r.data) || a.f.nome.localeCompare(b.f.nome));
    return linhas;
  }, [funcionarios, cargos, registrosMes, funcSelId]);


  const totalGeral = rows.reduce((s, r) => s + r.calc.liquido, 0);
  const totalExtras = rows.reduce((s, r) => s + r.calc.totalValorExtras, 0);
  const totalDesc = rows.reduce((s, r) => s + r.calc.totalDescontos, 0);
  const totalExcedentes = rows.reduce((s, r) => s + r.calc.totalValorExcedentes, 0);
  const totalHorasNormais = rows.reduce((s, r) => s + r.horasNormais, 0);
  const rowsComExcedente = rows.filter((r) => r.calc.totalHorasExcedentes > 0);

  const FILTROS = [
    { id: "tudo", label: "Tudo" },
    { id: "normais", label: "Só normais" },
    { id: "extras", label: "Só extras" },
  ];

  function imprimir() {
    window.print();
  }

  function exportCSV() {
    const meta = [
      ["Empresa", "PROSIGN"],
      ["Período de abrangência", mesRefExtenso(mesRef)],
      ["Funcionário(s)", funcSelId === "todos" ? "Todos" : rows[0]?.f.nome || ""],
      ["Funcionários no relatório", String(rows.length)],
      ["Visão", FILTROS.find((fl) => fl.id === filtro)?.label || ""],
      ["Gerado em", new Date().toLocaleString("pt-BR")],
      [],
    ];
    const header = ["Código","Nome","Função","H.Normais","H.Extras (até 40h)","Valor Extras","H.Excedentes","Valor Excedentes","Descontos","Líquido"];
    const lines = rows.map((r) => [r.f.codigo, r.f.nome, r.cargo?.funcao || "", r.horasNormais.toFixed(2), r.calc.totalHorasExtras.toFixed(2), r.calc.totalValorExtras.toFixed(2), r.calc.totalHorasExcedentes.toFixed(2), r.calc.totalValorExcedentes.toFixed(2), r.calc.totalDescontos.toFixed(2), r.calc.liquido.toFixed(2)]);
    const csv = [...meta, header, ...lines].map((l) => l.join(";")).join("\n");
    const blob = new Blob(["\uFEFF" + csv], { type: "text/csv;charset=utf-8;" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = funcSelId === "todos" ? `prosign_ponto_${mesRef}.csv` : `prosign_ponto_${mesRef}_${(rows[0]?.f.codigo || rows[0]?.f.nome || "func").replace(/\s+/g, "_")}.csv`;
    a.click();
    URL.revokeObjectURL(url);
  }

  return (
    <div>
      <style>{`
        @media print {
          /* Safari/WebKit tem um bug conhecido: elementos com
             display:flex ou display:grid às vezes não aparecem
             na impressão. Forçamos esses containers para block
             só no momento de imprimir. */
          .print-safe, .print-safe > * { display: block !important; }
          .print-safe-row > * { display: inline-block !important; margin-right: 18px !important; }
          /* Esta regra fica por último para vencer qualquer conflito
             de especificidade com as regras acima. */
          .no-print { display: none !important; }
          body { background: #fff !important; }
        }
      `}</style>

      <div className="print-safe" style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 18, flexWrap: "wrap", gap: 12 }}>
        <h2 style={{ margin: 0, fontSize: 18, fontWeight: 700 }}>Relatório mensal</h2>
        <div className="no-print" style={{ display: "flex", gap: 10, alignItems: "center", flexWrap: "wrap" }}>
          <select value={funcSelId} onChange={(e) => setFuncSelId(e.target.value)} style={selStyle}>
            <option value="todos">Todos os funcionários</option>
            {funcionarios.map((f) => <option key={f.id} value={f.id}>{f.codigo} — {f.nome}</option>)}
          </select>
          <MesPicker mesRef={mesRef} setMesRef={setMesRef} />
          <button onClick={imprimir} style={btnGhostSmall}>Imprimir</button>
          <button onClick={exportCSV} style={btnPrimary}>Exportar CSV</button>
        </div>
      </div>

      <Card style={{ padding: "16px 22px", marginBottom: 18, background: "#F8F6F0", border: `1px solid ${BORDER}` }}>
        <div className="print-safe-row" style={{ display: "flex", flexWrap: "wrap", gap: "6px 28px", fontSize: 13 }}>
          <span><strong>Empresa:</strong> PROSIGN</span>
          <span><strong>Período de abrangência:</strong> {mesRefExtenso(mesRef)}</span>
          <span><strong>Funcionário(s):</strong> {funcSelId === "todos" ? "Todos" : rows[0]?.f.nome || "-"}</span>
          <span><strong>Visão:</strong> {modo === "resumo" ? FILTROS.find((fl) => fl.id === filtro)?.label : "Detalhado (dia a dia)"}</span>
          <span style={{ color: MUTED }}><strong>Gerado em:</strong> {new Date().toLocaleString("pt-BR")}</span>
        </div>
      </Card>

      <div className="no-print" style={{ display: "flex", gap: 6, marginBottom: 18 }}>
        {[{ id: "resumo", label: "Resumo" }, { id: "detalhado", label: "Detalhado (dia a dia)" }].map((m) => (
          <button
            key={m.id}
            onClick={() => setModo(m.id)}
            style={{
              padding: "8px 16px", borderRadius: 8, border: `1px solid ${modo === m.id ? GOLD : BORDER}`,
              background: modo === m.id ? GOLD : "#fff", color: modo === m.id ? "#fff" : TEXT,
              fontSize: 13, fontWeight: 600, cursor: "pointer",
            }}
          >
            {m.label}
          </button>
        ))}
      </div>

      {modo === "resumo" ? (
      <>
      <div className="no-print" style={{ display: "flex", gap: 6, marginBottom: 18 }}>
        {FILTROS.map((fl) => (
          <button
            key={fl.id}
            onClick={() => setFiltro(fl.id)}
            style={{
              padding: "8px 16px", borderRadius: 8, border: `1px solid ${filtro === fl.id ? NAVY : BORDER}`,
              background: filtro === fl.id ? NAVY : "#fff", color: filtro === fl.id ? "#fff" : TEXT,
              fontSize: 13, fontWeight: 600, cursor: "pointer",
            }}
          >
            {fl.label}
          </button>
        ))}
      </div>

      <div className="print-safe" style={{ display: "grid", gridTemplateColumns: filtro === "tudo" ? "repeat(4, 1fr)" : "repeat(2, 1fr)", gap: 14, marginBottom: 18 }}>
        {filtro !== "extras" && <SummaryCard label="Horas normais" value={decimalToHHMM(totalHorasNormais)} color={NAVY} />}
        {filtro !== "normais" && <SummaryCard label="Extras (até 40h)" value={brl(totalExtras)} color={OK} />}
        {filtro === "tudo" && <SummaryCard label="Pagamento de Extras (>40h)" value={brl(totalExcedentes)} color={GOLD} />}
        {filtro === "tudo" && <SummaryCard label="Total de descontos" value={brl(totalDesc)} color={DANGER} />}
        {filtro === "tudo" && <SummaryCard label="Líquido geral" value={brl(totalGeral)} color={GOLD} dark />}
        {filtro === "normais" && <SummaryCard label="Média por funcionário" value={rows.length ? decimalToHHMM(totalHorasNormais / rows.length) : "-"} color={NAVY_DARK} dark />}
        {filtro === "extras" && <SummaryCard label="Valor total de extras" value={brl(totalExtras + totalExcedentes)} color={GOLD} dark />}
      </div>

      <Card style={{ padding: 0, overflow: "hidden" }}>
        <div style={{ overflowX: "auto" }}>
          <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 13 }}>
            <thead>
              <tr style={{ background: "#F0F2F6", textAlign: "left" }}>
                {[
                  "Funcionário",
                  ...(filtro !== "extras" ? ["H.Normais"] : []),
                  ...(filtro !== "normais" ? ["Distribuição", "H.Extras (40h)", "Extras (R$)"] : []),
                  ...(filtro === "tudo" ? ["Descontos", "Líquido"] : []),
                ].map((h) => (
                  <th key={h} style={{ padding: "10px 14px", fontWeight: 600, color: MUTED, fontSize: 11, textTransform: "uppercase", letterSpacing: 0.4 }}>{h}</th>
                ))}
              </tr>
            </thead>
            <tbody>
              {rows.map(({ f, cargo, calc, horasNormais }) => (
                <tr key={f.id} style={{ borderTop: `1px solid ${BORDER}` }}>
                  <td style={{ padding: "12px 14px" }}>
                    <div style={{ fontWeight: 600 }}>{f.nome}</div>
                    <div style={{ fontSize: 11, color: MUTED }}>{f.codigo} · {cargo?.funcao || "sem cargo"}</div>
                  </td>
                  {filtro !== "extras" && (
                    <td style={{ padding: "12px 14px", fontFamily: FONT_MONO, color: NAVY, fontWeight: 600 }}>{decimalToHHMM(horasNormais)}</td>
                  )}
                  {filtro !== "normais" && (
                    <>
                      <td style={{ padding: "12px 14px", width: 160 }}><StackedBar linhas={calc.linhas} /></td>
                      <td style={{ padding: "12px 14px", fontFamily: FONT_MONO }}>{decimalToHHMM(calc.totalHorasExtras)}</td>
                      <td style={{ padding: "12px 14px", fontFamily: FONT_MONO, color: OK }}>{brl(calc.totalValorExtras)}</td>
                    </>
                  )}
                  {filtro === "tudo" && (
                    <>
                      <td style={{ padding: "12px 14px", fontFamily: FONT_MONO, color: calc.totalDescontos > 0 ? DANGER : MUTED }}>{calc.totalDescontos > 0 ? `- ${brl(calc.totalDescontos)}` : "-"}</td>
                      <td style={{ padding: "12px 14px", fontFamily: FONT_MONO, fontWeight: 700 }}>{brl(calc.liquido)}</td>
                    </>
                  )}
                </tr>
              ))}
              {rows.length === 0 && <tr><td colSpan={6} style={{ padding: 20, color: MUTED, textAlign: "center" }}>Nenhum funcionário cadastrado.</td></tr>}
            </tbody>
          </table>
        </div>
      </Card>

      {filtro === "tudo" && rowsComExcedente.length > 0 && (
        <>
          <h3 style={{ fontSize: 15, fontWeight: 700, marginTop: 26, marginBottom: 12 }}>
            Pagamento de Extras <span style={{ color: MUTED, fontWeight: 400 }}>(horas acima do teto de 40h/mês)</span>
          </h3>
          <Card style={{ padding: 0, overflow: "hidden" }}>
            <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 13 }}>
              <thead>
                <tr style={{ background: "#FBF3E3", textAlign: "left" }}>
                  {["Funcionário","H.Excedentes","Valor Excedente"].map((h) => (
                    <th key={h} style={{ padding: "10px 14px", fontWeight: 600, color: "#8A6A20", fontSize: 11, textTransform: "uppercase", letterSpacing: 0.4 }}>{h}</th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {rowsComExcedente.map(({ f, cargo, calc }) => (
                  <tr key={f.id} style={{ borderTop: `1px solid ${BORDER}` }}>
                    <td style={{ padding: "12px 14px" }}>
                      <div style={{ fontWeight: 600 }}>{f.nome}</div>
                      <div style={{ fontSize: 11, color: MUTED }}>{f.codigo} · {cargo?.funcao || "sem cargo"}</div>
                    </td>
                    <td style={{ padding: "12px 14px", fontFamily: FONT_MONO }}>{decimalToHHMM(calc.totalHorasExcedentes)}</td>
                    <td style={{ padding: "12px 14px", fontFamily: FONT_MONO, color: GOLD, fontWeight: 700 }}>{brl(calc.totalValorExcedentes)}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </Card>
        </>
      )}
      </>
      ) : (
        <Card style={{ padding: 0, overflow: "hidden" }}>
          <div style={{ overflowX: "auto" }}>
            {carregando ? (
              <div style={{ padding: 20, color: MUTED, fontSize: 13 }}>Carregando...</div>
            ) : linhasDetalhadas.length === 0 ? (
              <div style={{ padding: 20, color: MUTED, fontSize: 13 }}>Nenhum dia registrado nesse mês.</div>
            ) : (
              <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 13 }}>
                <thead>
                  <tr style={{ background: "#F0F2F6", textAlign: "left" }}>
                    {[
                      ...(funcSelId === "todos" ? ["Funcionário"] : []),
                      "Dia", "Entrada/Saída", "Classificação", "Valor do dia",
                    ].map((h) => (
                      <th key={h} style={{ padding: "10px 14px", fontWeight: 600, color: MUTED, fontSize: 11, textTransform: "uppercase", letterSpacing: 0.4 }}>{h}</th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {linhasDetalhadas.map(({ f, r, c, valorHora }) => {
                    const tags = Object.entries(c).filter(([k, v]) => k !== "normal" && v > 0);
                    const valorDia = CAMPOS_LANC.reduce((s, cfg) => s + valorLinha(c[cfg.key] || 0, valorHora, cfg), 0); // não soma horas normais (já pagas no salário-base)
                    return (
                      <tr key={r.id} style={{ borderTop: `1px solid ${BORDER}` }}>
                        {funcSelId === "todos" && (
                          <td style={{ padding: "10px 14px" }}>
                            <div style={{ fontWeight: 600 }}>{f.nome}</div>
                            <div style={{ fontSize: 11, color: MUTED }}>{f.codigo}</div>
                          </td>
                        )}
                        <td style={{ padding: "10px 14px" }}>
                          <div style={{ fontWeight: 600 }}>{r.data.slice(8,10)}/{r.data.slice(5,7)} · {diaSemanaLabel(r.data)}{r.feriado ? " 🎉" : ""}</div>
                          {r.observacao && <div style={{ fontSize: 11, color: MUTED, fontStyle: "italic", marginTop: 2 }}>{r.observacao}</div>}
                        </td>
                        <td style={{ padding: "10px 14px", fontFamily: FONT_MONO }}>
                          {r.entrada}–{r.saida}
                          {r.entrada2 && <><br />{r.entrada2}–{r.saida2}</>}
                          {r.entrada3 && <><br />{r.entrada3}–{r.saida3}</>}
                          {r.almocoHoras > 0 && <div style={{ fontSize: 11, color: MUTED }}>🍽️ {decimalToHHMM(r.almocoHoras)}</div>}
                        </td>
                        <td style={{ padding: "10px 14px" }}>
                          {tags.length === 0 ? <span style={{ color: MUTED }}>só horas normais ({decimalToHHMM(c.normal)})</span> : tags.map(([k, v]) => (
                            <div key={k} style={{ color: BAR_COLORS[k] || MUTED }}>{CAMPOS_LANC.find((c2) => c2.key === k)?.label || k}: {decimalToHHMM(v)}</div>
                          ))}
                        </td>
                        <td style={{ padding: "10px 14px", fontFamily: FONT_MONO, fontWeight: 600, color: GOLD }}>{brl(valorDia)}</td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            )}
          </div>
        </Card>
      )}
    </div>
  );
}

// =========================================================
// Consulta — filtro livre por funcionário + intervalo de datas,
// pra conferir/bater com cálculos manuais (planilha, etc.)
// =========================================================
function ConsultaView({ funcionarios, cargos, session, setErro }) {
  const hoje = new Date().toISOString().slice(0, 10);
  const inicioMesAtual = hoje.slice(0, 8) + "01";

  const [selId, setSelId] = useState(funcionarios[0]?.id || "");
  const [dataInicio, setDataInicio] = useState(inicioMesAtual);
  const [dataFim, setDataFim] = useState(hoje);
  const [registros, setRegistros] = useState([]);
  const [carregando, setCarregando] = useState(false);

  const funcionario = funcionarios.find((f) => String(f.id) === String(selId));

  useEffect(() => {
    if (!selId || !dataInicio || !dataFim) return;
    setCarregando(true);
    sbRequest(`registros_ponto?select=*&funcionario_id=eq.${selId}&data=gte.${dataInicio}&data=lte.${dataFim}&order=data.asc`, session)
      .then((rows) => setRegistros((rows || []).map(registroFromRow)))
      .catch((e) => setErro(e.message))
      .finally(() => setCarregando(false));
  }, [selId, dataInicio, dataFim, session]); // eslint-disable-line

  if (!funcionarios.length) return <div style={{ color: MUTED }}>Cadastre um funcionário primeiro na aba "Funcionários".</div>;

  const salario = funcionario ? salarioBase(funcionario, cargos) : 0;
  const valorHora = salario / DIVISOR_HORA;

  const linhasDias = registros.map((r) => ({ r, c: classificarDia(r) }));

  const totalPeriodo = diaVazio();
  linhasDias.forEach(({ c }) => { Object.keys(totalPeriodo).forEach((k) => (totalPeriodo[k] += c[k])); });

  const resumoExtras = CAMPOS_LANC.map((cfg) => {
    const horas = totalPeriodo[cfg.key] || 0;
    const valor = valorLinha(horas, valorHora, cfg);
    return { ...cfg, horas, valor };
  });
  // NÃO soma horas normais aqui: elas já são pagas pelo salário-base fixo.
  // O total aqui é só o valor de horas extras/adicionais do período.
  const totalValorGeral = resumoExtras.reduce((s, l) => s + l.valor, 0);

  return (
    <div>
      <div style={{ display: "flex", gap: 12, marginBottom: 18, flexWrap: "wrap", alignItems: "end" }}>
        <Field label="Funcionário">
          <select value={selId} onChange={(e) => setSelId(e.target.value)} style={{ ...selStyle, minWidth: 240 }}>
            {funcionarios.map((f) => <option key={f.id} value={f.id}>{f.codigo} — {f.nome}</option>)}
          </select>
        </Field>
        <Field label="De">
          <input type="date" style={inputStyle} value={dataInicio} onChange={(e) => setDataInicio(e.target.value)} />
        </Field>
        <Field label="Até">
          <input type="date" style={inputStyle} value={dataFim} onChange={(e) => setDataFim(e.target.value)} />
        </Field>
      </div>

      {funcionario && (
        <Card style={{ marginBottom: 18 }}>
          <div style={{ fontSize: 12, color: MUTED, textTransform: "uppercase", letterSpacing: 0.5, marginBottom: 4 }}>Resumo do período</div>
          <div style={{ fontSize: 13, color: MUTED, fontFamily: FONT_MONO, marginBottom: 14 }}>
            Base: {brl(salario)} · Hora: {brl(valorHora)} · Horas normais: {decimalToHHMM(totalPeriodo.normal)}
          </div>
          <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(180px, 1fr))", gap: 10 }}>
            {resumoExtras.filter((l) => l.horas > 0).map((l) => (
              <div key={l.key} style={{ padding: 10, background: "#F0F2F6", borderRadius: 8 }}>
                <div style={{ fontSize: 11, color: MUTED }}>{l.label}</div>
                <div style={{ fontFamily: FONT_MONO, fontWeight: 700 }}>{decimalToHHMM(l.horas)}</div>
                <div style={{ fontFamily: FONT_MONO, color: GOLD, fontSize: 13 }}>{brl(l.valor)}</div>
              </div>
            ))}
            {resumoExtras.every((l) => l.horas === 0) && (
              <div style={{ color: MUTED, fontSize: 13 }}>Nenhuma hora extra/adicional no período.</div>
            )}
          </div>
          <div style={{ borderTop: `1px solid ${BORDER}`, marginTop: 14, paddingTop: 12, display: "flex", justifyContent: "space-between", fontWeight: 700 }}>
            <span>Valor total de extras/adicionais do período — sem separar dentro/fora do teto de 40h (equivale à soma de "Total extras até 40h" + "Pagamento de Extras &gt;40h" de Lançamentos)</span>
            <span style={{ fontFamily: FONT_MONO, color: GOLD }}>{brl(totalValorGeral)}</span>
          </div>
        </Card>
      )}

      <Card style={{ padding: 0, overflow: "hidden" }}>
        <div style={{ overflowX: "auto" }}>
          {carregando ? (
            <div style={{ padding: 20, color: MUTED, fontSize: 13 }}>Carregando...</div>
          ) : linhasDias.length === 0 ? (
            <div style={{ padding: 20, color: MUTED, fontSize: 13 }}>Nenhum dia registrado nesse período.</div>
          ) : (
            <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 13 }}>
              <thead>
                <tr style={{ background: "#F0F2F6", textAlign: "left" }}>
                  {["Dia", "Entrada/Saída", "Classificação", "Valor do dia"].map((h) => (
                    <th key={h} style={{ padding: "10px 14px", fontWeight: 600, color: MUTED, fontSize: 11, textTransform: "uppercase", letterSpacing: 0.4 }}>{h}</th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {linhasDias.map(({ r, c }) => {
                  const tags = Object.entries(c).filter(([k, v]) => k !== "normal" && v > 0);
                  const valorDia = CAMPOS_LANC.reduce((s, cfg) => s + valorLinha(c[cfg.key] || 0, valorHora, cfg), 0); // não soma horas normais (já pagas no salário-base)
                  return (
                    <tr key={r.id} style={{ borderTop: `1px solid ${BORDER}` }}>
                      <td style={{ padding: "10px 14px" }}>
                        <div style={{ fontWeight: 600 }}>{r.data.slice(8,10)}/{r.data.slice(5,7)} · {diaSemanaLabel(r.data)}{r.feriado ? " 🎉" : ""}</div>
                        {r.observacao && <div style={{ fontSize: 11, color: MUTED, fontStyle: "italic", marginTop: 2 }}>{r.observacao}</div>}
                      </td>
                      <td style={{ padding: "10px 14px", fontFamily: FONT_MONO }}>
                        {r.entrada}–{r.saida}
                        {r.entrada2 && <><br />{r.entrada2}–{r.saida2}</>}
                        {r.entrada3 && <><br />{r.entrada3}–{r.saida3}</>}
                        {r.almocoHoras > 0 && <div style={{ fontSize: 11, color: MUTED }}>🍽️ {decimalToHHMM(r.almocoHoras)}</div>}
                      </td>
                      <td style={{ padding: "10px 14px" }}>
                        {tags.length === 0 ? <span style={{ color: MUTED }}>só horas normais ({decimalToHHMM(c.normal)})</span> : tags.map(([k, v]) => (
                          <div key={k} style={{ color: BAR_COLORS[k] || MUTED }}>{CAMPOS_LANC.find((c2) => c2.key === k)?.label || k}: {decimalToHHMM(v)}</div>
                        ))}
                      </td>
                      <td style={{ padding: "10px 14px", fontFamily: FONT_MONO, fontWeight: 600, color: GOLD }}>{brl(valorDia)}</td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          )}
        </div>
      </Card>
    </div>
  );
}

// =========================================================
// Usuários — só admin vê. Gerencia nome/admin de cada perfil
// e quais áreas (ponto/comercial) cada um pode acessar.
// =========================================================
const AREAS_DISPONIVEIS = [
  { id: "ponto", label: "Controle de Ponto" },
  { id: "comercial", label: "Comercial" },
];

function UsuariosView({ session, setErro, meuId }) {
  const [perfis, setPerfis] = useState([]);
  const [areasPorUsuario, setAreasPorUsuario] = useState({}); // { user_id: Set(['ponto','comercial']) }
  const [carregando, setCarregando] = useState(false);
  const [salvandoId, setSalvandoId] = useState(null);
  const [showForm, setShowForm] = useState(false);
  const [novoEmail, setNovoEmail] = useState("");
  const [novaSenha, setNovaSenha] = useState("");
  const [criando, setCriando] = useState(false);
  const [avisoCriacao, setAvisoCriacao] = useState("");

  function carregar() {
    setCarregando(true);
    Promise.all([
      sbRequest("perfis?select=*&order=email.asc", session),
      sbRequest("usuarios_areas?select=*", session),
    ])
      .then(([p, ua]) => {
        setPerfis(p || []);
        const mapa = {};
        (ua || []).forEach((row) => {
          if (!mapa[row.user_id]) mapa[row.user_id] = new Set();
          mapa[row.user_id].add(row.area);
        });
        setAreasPorUsuario(mapa);
      })
      .catch((e) => setErro(e.message))
      .finally(() => setCarregando(false));
  }

  useEffect(() => { carregar(); }, []); // eslint-disable-line

  async function handleSalvarPerfil(p, campos) {
    setSalvandoId(p.id);
    setErro("");
    try {
      await sbRequest(`perfis?id=eq.${p.id}`, session, { method: "PATCH", body: campos });
      setPerfis((ps) => ps.map((x) => (x.id === p.id ? { ...x, ...campos } : x)));
    } catch (e) { setErro(e.message); }
    finally { setSalvandoId(null); }
  }

  async function handleToggleArea(userId, area, marcado) {
    setSalvandoId(userId);
    setErro("");
    try {
      if (marcado) {
        await sbRequest("usuarios_areas", session, { method: "POST", body: { user_id: userId, area } });
      } else {
        await sbRequest(`usuarios_areas?user_id=eq.${userId}&area=eq.${area}`, session, { method: "DELETE" });
      }
      setAreasPorUsuario((mapa) => {
        const novo = { ...mapa };
        const atual = new Set(novo[userId] || []);
        if (marcado) atual.add(area); else atual.delete(area);
        novo[userId] = atual;
        return novo;
      });
    } catch (e) { setErro(e.message); }
    finally { setSalvandoId(null); }
  }

  async function handleExcluirUsuario(p) {
    if (p.id === meuId) return;
    if (!window.confirm(`Remover o acesso de "${p.email}"? Ele(a) não vai mais conseguir ver nenhuma área do sistema.\n\n(O login continua existindo no Supabase — pra apagar de vez a conta, isso só pode ser feito no painel do Supabase em Authentication → Users.)`)) return;
    setSalvandoId(p.id);
    setErro("");
    try {
      await sbRequest(`usuarios_areas?user_id=eq.${p.id}`, session, { method: "DELETE" });
      await sbRequest(`perfis?id=eq.${p.id}`, session, { method: "DELETE" });
      setPerfis((ps) => ps.filter((x) => x.id !== p.id));
      setAreasPorUsuario((mapa) => {
        const novo = { ...mapa };
        delete novo[p.id];
        return novo;
      });
    } catch (e) { setErro(e.message); }
    finally { setSalvandoId(null); }
  }

  async function handleCriarUsuario() {
    if (!novoEmail || novaSenha.length < 6) {
      setErro("Preencha o e-mail e uma senha com pelo menos 6 caracteres.");
      return;
    }
    setCriando(true);
    setErro("");
    setAvisoCriacao("");
    try {
      const data = await sbSignup(novoEmail, novaSenha);
      // Se o Supabase exigir confirmação por e-mail, não vem access_token
      // ainda — o usuário só consegue logar depois de clicar no link.
      if (!data.access_token) {
        setAvisoCriacao(`Usuário "${novoEmail}" criado. Como a confirmação por e-mail está ativada no Supabase, ele só vai conseguir entrar depois de confirmar o e-mail recebido.`);
      } else {
        setAvisoCriacao(`Usuário "${novoEmail}" criado e já pode fazer login.`);
      }
      setNovoEmail("");
      setNovaSenha("");
      setShowForm(false);
      carregar();
    } catch (e) { setErro(e.message); }
    finally { setCriando(false); }
  }

  return (
    <div>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 18 }}>
        <h2 style={{ margin: 0, fontSize: 18, fontWeight: 700 }}>Usuários ({perfis.length})</h2>
        <button onClick={() => { setShowForm(true); setAvisoCriacao(""); }} style={btnPrimary}><Plus size={16} /> Novo usuário</button>
      </div>

      {avisoCriacao && (
        <div style={{ background: "#EAF4EE", color: OK, padding: 12, borderRadius: 8, marginBottom: 14, fontSize: 13 }}>{avisoCriacao}</div>
      )}

      {showForm && (
        <Card style={{ marginBottom: 18 }}>
          <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 16 }}>
            <h3 style={{ margin: 0, fontSize: 15 }}>Novo usuário</h3>
            <button onClick={() => setShowForm(false)} style={{ background: "none", border: "none", cursor: "pointer", color: MUTED }}><X size={18} /></button>
          </div>
          <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 12 }}>
            <Field label="E-mail">
              <input type="email" style={inputStyle} value={novoEmail} onChange={(e) => setNovoEmail(e.target.value)} />
            </Field>
            <Field label="Senha provisória (mín. 6 caracteres)">
              <input type="text" style={inputStyle} value={novaSenha} onChange={(e) => setNovaSenha(e.target.value)} />
            </Field>
          </div>
          <div style={{ fontSize: 12, color: MUTED, marginTop: 10 }}>
            Depois de criado, defina aqui embaixo se é admin e quais áreas ele acessa. Avise a senha provisória pra pessoa — ela pode trocar depois fazendo login.
          </div>
          <div style={{ display: "flex", justifyContent: "flex-end", gap: 8, marginTop: 16 }}>
            <button onClick={() => setShowForm(false)} style={btnGhostSmall}>Cancelar</button>
            <button onClick={handleCriarUsuario} disabled={criando} style={btnPrimary}><Save size={15} /> {criando ? "Criando..." : "Criar usuário"}</button>
          </div>
        </Card>
      )}

      <div style={{ color: MUTED, fontSize: 13, marginBottom: 14 }}>
        Aqui você define nome, se é administrador (acesso total) e quais áreas cada um pode ver.
      </div>

      {carregando ? (
        <div style={{ color: MUTED, fontSize: 13 }}>Carregando...</div>
      ) : (
        <Card style={{ padding: 0, overflow: "hidden" }}>
          <div style={{ overflowX: "auto" }}>
            <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 13 }}>
              <thead>
                <tr style={{ background: "#F0F2F6", textAlign: "left" }}>
                  {["E-mail", "Nome", "Admin (acesso total)", ...AREAS_DISPONIVEIS.map((a) => a.label), "Ações"].map((h) => (
                    <th key={h} style={{ padding: "10px 14px", fontWeight: 600, color: MUTED, fontSize: 11, textTransform: "uppercase", letterSpacing: 0.4 }}>{h}</th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {perfis.map((p) => {
                  const areas = areasPorUsuario[p.id] || new Set();
                  const salvando = salvandoId === p.id;
                  return (
                    <tr key={p.id} style={{ borderTop: `1px solid ${BORDER}` }}>
                      <td style={{ padding: "10px 14px" }}>
                        {p.email}{p.id === meuId && <span style={{ color: MUTED, fontSize: 11 }}> (você)</span>}
                      </td>
                      <td style={{ padding: "10px 14px" }}>
                        <input
                          style={{ ...inputStyle, width: 160 }}
                          defaultValue={p.nome || ""}
                          placeholder="Nome"
                          onBlur={(e) => {
                            if (e.target.value !== (p.nome || "")) handleSalvarPerfil(p, { nome: e.target.value || null });
                          }}
                        />
                      </td>
                      <td style={{ padding: "10px 14px" }}>
                        <input
                          type="checkbox"
                          checked={!!p.is_admin}
                          disabled={salvando}
                          onChange={(e) => handleSalvarPerfil(p, { is_admin: e.target.checked })}
                        />
                      </td>
                      {AREAS_DISPONIVEIS.map((a) => (
                        <td key={a.id} style={{ padding: "10px 14px" }}>
                          <input
                            type="checkbox"
                            checked={p.is_admin || areas.has(a.id)}
                            disabled={salvando || p.is_admin}
                            onChange={(e) => handleToggleArea(p.id, a.id, e.target.checked)}
                          />
                        </td>
                      ))}
                      <td style={{ padding: "10px 14px" }}>
                        {p.id !== meuId && (
                          <button
                            onClick={() => handleExcluirUsuario(p)}
                            disabled={salvando}
                            title="Remover acesso deste usuário"
                            style={{ ...btnDangerSmall, display: "flex", alignItems: "center", gap: 6 }}
                          >
                            <Trash2 size={14} /> Excluir
                          </button>
                        )}
                      </td>
                    </tr>
                  );
                })}
                {perfis.length === 0 && (
                  <tr><td colSpan={4 + AREAS_DISPONIVEIS.length} style={{ padding: 20, color: MUTED, textAlign: "center" }}>Nenhum usuário encontrado.</td></tr>
                )}
              </tbody>
            </table>
          </div>
        </Card>
      )}
    </div>
  );
}

// =========================================================
// Comercial — mapeamento JS <-> colunas do banco
// =========================================================
function clienteFromRow(r) { return { id: r.id, nome: r.nome }; }

function orcamentoFromRow(r) {
  return {
    id: r.id, evento: r.evento, clienteId: r.cliente_id, clienteNome: r.clientes?.nome || null,
    local: r.local, dataEvento: r.data_evento, valor: Number(r.valor || 0),
    status: r.status, mesRef: r.mes_ref,
  };
}

function faturamentoFromRow(r) {
  return {
    id: r.id, orcamentoId: r.orcamento_id, clienteId: r.cliente_id,
    clienteNome: r.clientes?.nome || null, orcamentoEvento: r.orcamentos?.evento || null,
    valor: Number(r.valor || 0), dataFaturamento: r.data_faturamento, mesRef: r.mes_ref,
  };
}

function previsaoFromRow(r) { return { id: r.id, ano: r.ano, mes: r.mes, valor: Number(r.valor_previsto || 0) }; }

const STATUS_ORCAMENTO = [
  { id: "orcado", label: "Orçado", color: MUTED },
  { id: "em_analise", label: "Em análise", color: GOLD },
  { id: "aprovado", label: "Aprovado", color: OK },
  { id: "nao_aprovado", label: "Não aprovado", color: DANGER },
];
function statusInfo(id) { return STATUS_ORCAMENTO.find((s) => s.id === id) || STATUS_ORCAMENTO[0]; }

// Garante que um orçamento aprovado tenha um lançamento de faturamento
// vinculado (não duplica se já existir). Chamado sempre que um orçamento
// é salvo com status "aprovado".
async function garantirFaturamento(session, orcamentoRow) {
  const existentes = await sbRequest(`faturamento?select=id&orcamento_id=eq.${orcamentoRow.id}`, session);
  if (existentes && existentes.length > 0) return;
  await sbRequest("faturamento", session, {
    method: "POST",
    body: {
      orcamento_id: orcamentoRow.id,
      cliente_id: orcamentoRow.cliente_id,
      valor: orcamentoRow.valor,
      data_faturamento: orcamentoRow.data_evento || new Date().toISOString().slice(0, 10),
      mes_ref: orcamentoRow.mes_ref,
    },
  });
}

const MESES_ABREV = ["Jan","Fev","Mar","Abr","Mai","Jun","Jul","Ago","Set","Out","Nov","Dez"];

// =========================================================
// Comercial — container com navegação interna
// =========================================================
function ComercialView({ session, setErro }) {
  const [subtab, setSubtab] = useState("dashboard");
  const [clientes, setClientes] = useState([]);
  const [carregandoClientes, setCarregandoClientes] = useState(false);

  function carregarClientes() {
    setCarregandoClientes(true);
    sbRequest("clientes?select=*&order=nome.asc", session)
      .then((rows) => setClientes((rows || []).map(clienteFromRow)))
      .catch((e) => setErro(e.message))
      .finally(() => setCarregandoClientes(false));
  }

  useEffect(() => { carregarClientes(); }, []); // eslint-disable-line

  const SUBABAS = [
    { id: "dashboard", label: "Dashboard" },
    { id: "orcamentos", label: "Orçamentos" },
    { id: "clientes", label: "Clientes" },
    { id: "previsao", label: "Previsão Orçamentária" },
    { id: "faturamento", label: "Faturamento" },
  ];

  return (
    <div>
      <h2 style={{ margin: "0 0 18px", fontSize: 18, fontWeight: 700 }}>Comercial</h2>
      <div style={{ display: "flex", gap: 6, marginBottom: 18, flexWrap: "wrap" }}>
        {SUBABAS.map((s) => (
          <button
            key={s.id}
            onClick={() => setSubtab(s.id)}
            style={{
              padding: "8px 16px", borderRadius: 8, border: `1px solid ${subtab === s.id ? GOLD : BORDER}`,
              background: subtab === s.id ? GOLD : "#fff", color: subtab === s.id ? "#fff" : TEXT,
              fontSize: 13, fontWeight: 600, cursor: "pointer",
            }}
          >
            {s.label}
          </button>
        ))}
      </div>

      {carregandoClientes ? (
        <div style={{ color: MUTED, fontSize: 13 }}>Carregando...</div>
      ) : (
        <>
          {subtab === "dashboard" && <DashboardComercialView session={session} setErro={setErro} clientes={clientes} />}
          {subtab === "orcamentos" && <OrcamentosComercialView session={session} setErro={setErro} clientes={clientes} />}
          {subtab === "clientes" && <ClientesComercialView session={session} setErro={setErro} clientes={clientes} setClientes={setClientes} />}
          {subtab === "previsao" && <PrevisaoComercialView session={session} setErro={setErro} />}
          {subtab === "faturamento" && <FaturamentoComercialView session={session} setErro={setErro} clientes={clientes} />}
        </>
      )}
    </div>
  );
}

// =========================================================
// Comercial · Clientes
// =========================================================
function ClientesComercialView({ session, setErro, clientes, setClientes }) {
  const [editing, setEditing] = useState(null);
  const [showForm, setShowForm] = useState(false);
  const [nome, setNome] = useState("");
  const [salvando, setSalvando] = useState(false);

  async function handleSave() {
    if (!nome.trim()) return;
    setSalvando(true);
    setErro("");
    try {
      if (editing) {
        const [row] = await sbRequest(`clientes?id=eq.${editing.id}`, session, { method: "PATCH", body: { nome: nome.trim() } });
        setClientes(clientes.map((c) => (c.id === editing.id ? clienteFromRow(row) : c)).sort((a, b) => a.nome.localeCompare(b.nome)));
      } else {
        const [row] = await sbRequest("clientes", session, { method: "POST", body: { nome: nome.trim() } });
        setClientes([...clientes, clienteFromRow(row)].sort((a, b) => a.nome.localeCompare(b.nome)));
      }
      setShowForm(false);
      setEditing(null);
      setNome("");
    } catch (e) { setErro(e.message); }
    finally { setSalvando(false); }
  }

  async function handleDelete(id) {
    setErro("");
    try {
      await sbRequest(`clientes?id=eq.${id}`, session, { method: "DELETE" });
      setClientes(clientes.filter((c) => c.id !== id));
    } catch (e) {
      setErro("Não foi possível excluir — esse cliente já tem orçamentos vinculados.");
    }
  }

  return (
    <div>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 18 }}>
        <h3 style={{ margin: 0, fontSize: 16, fontWeight: 700 }}>Clientes ({clientes.length})</h3>
        <button onClick={() => { setEditing(null); setNome(""); setShowForm(true); }} style={btnPrimary}><Plus size={16} /> Novo cliente</button>
      </div>

      {showForm && (
        <Card style={{ marginBottom: 18 }}>
          <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 12 }}>
            <h4 style={{ margin: 0, fontSize: 14 }}>{editing ? "Editar cliente" : "Novo cliente"}</h4>
            <button onClick={() => setShowForm(false)} style={{ background: "none", border: "none", cursor: "pointer", color: MUTED }}><X size={18} /></button>
          </div>
          <Field label="Nome">
            <input style={inputStyle} value={nome} onChange={(e) => setNome(e.target.value)} />
          </Field>
          <div style={{ display: "flex", justifyContent: "flex-end", gap: 8, marginTop: 14 }}>
            <button onClick={() => setShowForm(false)} style={btnGhostSmall}>Cancelar</button>
            <button onClick={handleSave} disabled={salvando} style={btnPrimary}><Save size={15} /> {salvando ? "Salvando..." : "Salvar"}</button>
          </div>
        </Card>
      )}

      <Card style={{ padding: 0, overflow: "hidden" }}>
        <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 13 }}>
          <tbody>
            {clientes.map((c) => (
              <tr key={c.id} style={{ borderTop: `1px solid ${BORDER}` }}>
                <td style={{ padding: "10px 14px", fontWeight: 600 }}>{c.nome}</td>
                <td style={{ padding: "10px 14px", textAlign: "right" }}>
                  <button onClick={() => { setEditing(c); setNome(c.nome); setShowForm(true); }} style={btnGhostSmall}>Editar</button>{" "}
                  <button onClick={() => handleDelete(c.id)} style={btnDangerSmall}><Trash2 size={13} /></button>
                </td>
              </tr>
            ))}
            {clientes.length === 0 && <tr><td style={{ padding: 20, color: MUTED, textAlign: "center" }}>Nenhum cliente cadastrado.</td></tr>}
          </tbody>
        </table>
      </Card>
    </div>
  );
}

// =========================================================
// Comercial · Orçamentos
// =========================================================
function OrcamentosComercialView({ session, setErro, clientes }) {
  const [mesRef, setMesRef] = useState(() => {
    const d = new Date();
    return `${d.getFullYear()}-${MESES[d.getMonth()]}`;
  });
  const [registros, setRegistros] = useState([]);
  const [carregando, setCarregando] = useState(false);
  const [filtroStatus, setFiltroStatus] = useState("todos");
  const [showForm, setShowForm] = useState(false);
  const [editing, setEditing] = useState(null);
  const [salvando, setSalvando] = useState(false);

  const blankForm = { evento: "", clienteId: "", local: "", dataEvento: "", valor: 0, status: "orcado" };
  const [form, setForm] = useState(blankForm);

  function carregar() {
    setCarregando(true);
    sbRequest(`orcamentos?select=*,clientes(nome)&mes_ref=eq.${mesRef}-01&order=data_evento.asc`, session)
      .then((rows) => setRegistros((rows || []).map(orcamentoFromRow)))
      .catch((e) => setErro(e.message))
      .finally(() => setCarregando(false));
  }
  useEffect(() => { carregar(); }, [mesRef]); // eslint-disable-line

  function abrirNovo() {
    setEditing(null);
    setForm({ ...blankForm, clienteId: clientes[0]?.id || "" });
    setShowForm(true);
  }
  function abrirEditar(o) {
    setEditing(o);
    setForm({ evento: o.evento, clienteId: o.clienteId || "", local: o.local || "", dataEvento: o.dataEvento || "", valor: o.valor, status: o.status });
    setShowForm(true);
  }

  async function handleSalvar() {
    if (!form.evento || !form.valor) return;
    setSalvando(true);
    setErro("");
    try {
      const mesRefCalc = form.dataEvento ? `${form.dataEvento.slice(0, 7)}-01` : `${mesRef}-01`;
      const body = {
        evento: form.evento, cliente_id: form.clienteId || null, local: form.local || null,
        data_evento: form.dataEvento || null, valor: form.valor, status: form.status, mes_ref: mesRefCalc,
      };
      let saved;
      if (editing) {
        [saved] = await sbRequest(`orcamentos?id=eq.${editing.id}`, session, { method: "PATCH", body });
      } else {
        [saved] = await sbRequest("orcamentos", session, { method: "POST", body });
      }
      if (saved.status === "aprovado") await garantirFaturamento(session, saved);
      setShowForm(false);
      setEditing(null);
      carregar();
    } catch (e) { setErro(e.message); }
    finally { setSalvando(false); }
  }

  async function handleExcluir(id) {
    setErro("");
    try {
      await sbRequest(`orcamentos?id=eq.${id}`, session, { method: "DELETE" });
      setRegistros((rs) => rs.filter((r) => r.id !== id));
    } catch (e) { setErro(e.message); }
  }

  async function handleMudarStatus(o, novoStatus) {
    setErro("");
    try {
      const [saved] = await sbRequest(`orcamentos?id=eq.${o.id}`, session, { method: "PATCH", body: { status: novoStatus } });
      if (novoStatus === "aprovado") await garantirFaturamento(session, saved);
      setRegistros((rs) => rs.map((r) => (r.id === o.id ? { ...r, status: novoStatus } : r)));
    } catch (e) { setErro(e.message); }
  }

  const rowsFiltradas = filtroStatus === "todos" ? registros : registros.filter((r) => r.status === filtroStatus);
  const totalFiltrado = rowsFiltradas.reduce((s, r) => s + r.valor, 0);

  return (
    <div>
      <div style={{ display: "flex", gap: 12, marginBottom: 18, flexWrap: "wrap", alignItems: "center", justifyContent: "space-between" }}>
        <div style={{ display: "flex", gap: 12, alignItems: "center", flexWrap: "wrap" }}>
          <MesPicker mesRef={mesRef} setMesRef={setMesRef} />
          <select value={filtroStatus} onChange={(e) => setFiltroStatus(e.target.value)} style={selStyle}>
            <option value="todos">Todos os status</option>
            {STATUS_ORCAMENTO.map((s) => <option key={s.id} value={s.id}>{s.label}</option>)}
          </select>
        </div>
        <button onClick={abrirNovo} style={btnPrimary}><Plus size={16} /> Novo orçamento</button>
      </div>

      {showForm && (
        <Card style={{ marginBottom: 18 }}>
          <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 16 }}>
            <h4 style={{ margin: 0, fontSize: 14 }}>{editing ? "Editar orçamento" : "Novo orçamento"}</h4>
            <button onClick={() => setShowForm(false)} style={{ background: "none", border: "none", cursor: "pointer", color: MUTED }}><X size={18} /></button>
          </div>
          <div style={{ display: "grid", gridTemplateColumns: "2fr 1fr", gap: 12 }}>
            <Field label="Nome do evento"><input style={inputStyle} value={form.evento} onChange={(e) => setForm({ ...form, evento: e.target.value })} /></Field>
            <Field label="Cliente">
              <select style={inputStyle} value={form.clienteId} onChange={(e) => setForm({ ...form, clienteId: e.target.value })}>
                <option value="">Selecione...</option>
                {clientes.map((c) => <option key={c.id} value={c.id}>{c.nome}</option>)}
              </select>
            </Field>
            <Field label="Local"><input style={inputStyle} value={form.local} onChange={(e) => setForm({ ...form, local: e.target.value })} /></Field>
            <Field label="Data do evento"><input type="date" style={inputStyle} value={form.dataEvento} onChange={(e) => setForm({ ...form, dataEvento: e.target.value })} /></Field>
            <Field label="Valor (R$)"><input type="number" step="0.01" style={inputStyle} value={form.valor} onChange={(e) => setForm({ ...form, valor: parseFloat(e.target.value) || 0 })} /></Field>
            <Field label="Status">
              <select style={inputStyle} value={form.status} onChange={(e) => setForm({ ...form, status: e.target.value })}>
                {STATUS_ORCAMENTO.map((s) => <option key={s.id} value={s.id}>{s.label}</option>)}
              </select>
            </Field>
          </div>
          {form.status === "aprovado" && (
            <div style={{ fontSize: 12, color: MUTED, marginTop: 10 }}>
              Ao salvar como "Aprovado", um lançamento de faturamento é gerado automaticamente (se ainda não existir).
            </div>
          )}
          <div style={{ display: "flex", justifyContent: "flex-end", gap: 8, marginTop: 16 }}>
            <button onClick={() => setShowForm(false)} style={btnGhostSmall}>Cancelar</button>
            <button onClick={handleSalvar} disabled={salvando} style={btnPrimary}><Save size={15} /> {salvando ? "Salvando..." : "Salvar"}</button>
          </div>
        </Card>
      )}

      <Card style={{ padding: 0, overflow: "hidden" }}>
        <div style={{ overflowX: "auto" }}>
          <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 13 }}>
            <thead>
              <tr style={{ background: "#F0F2F6", textAlign: "left" }}>
                {["Data", "Evento", "Cliente", "Local", "Valor", "Status", ""].map((h) => (
                  <th key={h} style={{ padding: "10px 14px", fontWeight: 600, color: MUTED, fontSize: 11, textTransform: "uppercase", letterSpacing: 0.4 }}>{h}</th>
                ))}
              </tr>
            </thead>
            <tbody>
              {carregando ? (
                <tr><td colSpan={7} style={{ padding: 20, color: MUTED, textAlign: "center" }}>Carregando...</td></tr>
              ) : rowsFiltradas.length === 0 ? (
                <tr><td colSpan={7} style={{ padding: 20, color: MUTED, textAlign: "center" }}>Nenhum orçamento nesse filtro.</td></tr>
              ) : rowsFiltradas.map((r) => {
                const st = statusInfo(r.status);
                return (
                  <tr key={r.id} style={{ borderTop: `1px solid ${BORDER}` }}>
                    <td style={{ padding: "10px 14px", fontFamily: FONT_MONO, whiteSpace: "nowrap" }}>{r.dataEvento ? r.dataEvento.slice(8,10)+"/"+r.dataEvento.slice(5,7) : "-"}</td>
                    <td style={{ padding: "10px 14px", fontWeight: 600 }}>{r.evento}</td>
                    <td style={{ padding: "10px 14px" }}>{r.clienteNome || "-"}</td>
                    <td style={{ padding: "10px 14px", color: MUTED }}>{r.local || "-"}</td>
                    <td style={{ padding: "10px 14px", fontFamily: FONT_MONO }}>{brl(r.valor)}</td>
                    <td style={{ padding: "10px 14px" }}>
                      <select
                        value={r.status}
                        onChange={(e) => handleMudarStatus(r, e.target.value)}
                        style={{ ...selStyle, padding: "5px 8px", fontSize: 12, color: st.color, fontWeight: 600 }}
                      >
                        {STATUS_ORCAMENTO.map((s) => <option key={s.id} value={s.id}>{s.label}</option>)}
                      </select>
                    </td>
                    <td style={{ padding: "10px 14px", textAlign: "right", whiteSpace: "nowrap" }}>
                      <button onClick={() => abrirEditar(r)} style={btnGhostSmall}>Editar</button>{" "}
                      <button onClick={() => handleExcluir(r.id)} style={btnDangerSmall}><Trash2 size={13} /></button>
                    </td>
                  </tr>
                );
              })}
            </tbody>
            {rowsFiltradas.length > 0 && (
              <tfoot>
                <tr style={{ borderTop: `2px solid ${BORDER}` }}>
                  <td colSpan={4} style={{ padding: "10px 14px", fontWeight: 700 }}>Total ({rowsFiltradas.length})</td>
                  <td style={{ padding: "10px 14px", fontFamily: FONT_MONO, fontWeight: 700 }}>{brl(totalFiltrado)}</td>
                  <td colSpan={2}></td>
                </tr>
              </tfoot>
            )}
          </table>
        </div>
      </Card>
    </div>
  );
}

// =========================================================
// Comercial · Previsão Orçamentária
// =========================================================
function PrevisaoComercialView({ session, setErro }) {
  const anoAtual = new Date().getFullYear();
  const [ano, setAno] = useState(anoAtual + 1);
  const [valores, setValores] = useState(() => Array(12).fill(0));
  const [carregando, setCarregando] = useState(false);
  const [salvando, setSalvando] = useState(false);
  const [anoBase, setAnoBase] = useState(anoAtual);
  const [percentual, setPercentual] = useState(10);
  const [aplicando, setAplicando] = useState(false);

  function carregar() {
    setCarregando(true);
    sbRequest(`previsao_orcamentaria?select=*&ano=eq.${ano}`, session)
      .then((rows) => {
        const novos = Array(12).fill(0);
        (rows || []).map(previsaoFromRow).forEach((p) => { novos[p.mes - 1] = p.valor; });
        setValores(novos);
      })
      .catch((e) => setErro(e.message))
      .finally(() => setCarregando(false));
  }
  useEffect(() => { carregar(); }, [ano]); // eslint-disable-line

  async function handleAplicarPercentual() {
    setAplicando(true);
    setErro("");
    try {
      const rows = await sbRequest(
        `orcamentos?select=valor,mes_ref&status=eq.aprovado&mes_ref=gte.${anoBase}-01-01&mes_ref=lt.${anoBase + 1}-01-01`,
        session
      );
      const somaPorMes = Array(12).fill(0);
      (rows || []).forEach((r) => {
        const mes = Number(r.mes_ref.slice(5, 7)) - 1;
        somaPorMes[mes] += Number(r.valor || 0);
      });
      const fator = 1 + (percentual || 0) / 100;
      setValores(somaPorMes.map((v) => Math.round(v * fator * 100) / 100));
    } catch (e) { setErro(e.message); }
    finally { setAplicando(false); }
  }

  async function handleSalvar() {
    setSalvando(true);
    setErro("");
    try {
      const body = valores.map((v, i) => ({ ano, mes: i + 1, valor_previsto: v }));
      await sbRequest("previsao_orcamentaria?on_conflict=ano,mes", session, {
        method: "POST", body, extraHeaders: { Prefer: "resolution=merge-duplicates,return=representation" },
      });
    } catch (e) { setErro(e.message); }
    finally { setSalvando(false); }
  }

  const trimestres = [0, 1, 2, 3].map((t) => valores.slice(t * 3, t * 3 + 3).reduce((s, v) => s + v, 0));
  const totalAno = valores.reduce((s, v) => s + v, 0);

  return (
    <div>
      <div style={{ display: "flex", gap: 12, marginBottom: 18, flexWrap: "wrap", alignItems: "center" }}>
        <Field label="Ano da previsão">
          <select style={selStyle} value={ano} onChange={(e) => setAno(Number(e.target.value))}>
            {[anoAtual, anoAtual + 1, anoAtual + 2].map((a) => <option key={a} value={a}>{a}</option>)}
          </select>
        </Field>
      </div>

      <Card style={{ marginBottom: 18, background: "#F8F6F0" }}>
        <div style={{ fontSize: 13, fontWeight: 600, marginBottom: 10 }}>Preencher automaticamente a partir do realizado</div>
        <div style={{ display: "flex", gap: 12, alignItems: "end", flexWrap: "wrap" }}>
          <Field label="Ano base (realizado)">
            <select style={selStyle} value={anoBase} onChange={(e) => setAnoBase(Number(e.target.value))}>
              {[anoAtual - 1, anoAtual].map((a) => <option key={a} value={a}>{a}</option>)}
            </select>
          </Field>
          <Field label="Reajuste (%)">
            <input type="number" step="0.1" style={inputStyle} value={percentual} onChange={(e) => setPercentual(parseFloat(e.target.value) || 0)} />
          </Field>
          <button onClick={handleAplicarPercentual} disabled={aplicando} style={btnGhostSmall}>
            {aplicando ? "Calculando..." : `Aplicar: cada mês = mesmo mês de ${anoBase} × (1 + ${percentual}%)`}
          </button>
        </div>
      </Card>

      {carregando ? (
        <div style={{ color: MUTED, fontSize: 13 }}>Carregando...</div>
      ) : (
        <Card style={{ padding: 0, overflow: "hidden" }}>
          <div style={{ overflowX: "auto" }}>
            <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 13 }}>
              <thead>
                <tr style={{ background: "#F0F2F6", textAlign: "left" }}>
                  {MESES_ABREV.map((m) => (
                    <th key={m} style={{ padding: "10px 12px", fontWeight: 600, color: MUTED, fontSize: 11, textTransform: "uppercase" }}>{m}</th>
                  ))}
                </tr>
              </thead>
              <tbody>
                <tr>
                  {valores.map((v, i) => (
                    <td key={i} style={{ padding: "8px 10px" }}>
                      <input
                        type="number" step="0.01" style={{ ...inputStyle, width: 100, fontFamily: FONT_MONO, fontSize: 12 }}
                        value={v}
                        onChange={(e) => {
                          const novos = [...valores];
                          novos[i] = parseFloat(e.target.value) || 0;
                          setValores(novos);
                        }}
                      />
                    </td>
                  ))}
                </tr>
              </tbody>
            </table>
          </div>
        </Card>
      )}

      <div style={{ display: "grid", gridTemplateColumns: "repeat(4, 1fr)", gap: 14, marginTop: 18 }}>
        {trimestres.map((t, i) => (
          <SummaryCard key={i} label={`${i + 1}º trimestre`} value={brl(t)} color={NAVY} />
        ))}
      </div>
      <div style={{ marginTop: 14 }}>
        <SummaryCard label={`Total previsto ${ano}`} value={brl(totalAno)} color={GOLD} dark />
      </div>

      <button onClick={handleSalvar} disabled={salvando} style={{ ...btnPrimary, marginTop: 18 }}>
        <Save size={15} /> {salvando ? "Salvando..." : "Salvar previsão"}
      </button>
    </div>
  );
}

// =========================================================
// Comercial · Faturamento
// =========================================================
function FaturamentoComercialView({ session, setErro, clientes }) {
  const [mesRef, setMesRef] = useState(() => {
    const d = new Date();
    return `${d.getFullYear()}-${MESES[d.getMonth()]}`;
  });
  const [registros, setRegistros] = useState([]);
  const [carregando, setCarregando] = useState(false);
  const [showForm, setShowForm] = useState(false);
  const [salvando, setSalvando] = useState(false);
  const blankForm = { clienteId: "", valor: 0, dataFaturamento: "" };
  const [form, setForm] = useState(blankForm);

  function carregar() {
    setCarregando(true);
    sbRequest(`faturamento?select=*,clientes(nome),orcamentos(evento)&mes_ref=eq.${mesRef}-01&order=data_faturamento.asc`, session)
      .then((rows) => setRegistros((rows || []).map(faturamentoFromRow)))
      .catch((e) => setErro(e.message))
      .finally(() => setCarregando(false));
  }
  useEffect(() => { carregar(); }, [mesRef]); // eslint-disable-line

  async function handleSalvarValor(r, novoValor) {
    setErro("");
    try {
      await sbRequest(`faturamento?id=eq.${r.id}`, session, { method: "PATCH", body: { valor: novoValor } });
      setRegistros((rs) => rs.map((x) => (x.id === r.id ? { ...x, valor: novoValor } : x)));
    } catch (e) { setErro(e.message); }
  }

  async function handleSalvarData(r, novaData) {
    setErro("");
    try {
      await sbRequest(`faturamento?id=eq.${r.id}`, session, { method: "PATCH", body: { data_faturamento: novaData || null } });
      setRegistros((rs) => rs.map((x) => (x.id === r.id ? { ...x, dataFaturamento: novaData } : x)));
    } catch (e) { setErro(e.message); }
  }

  async function handleExcluir(id) {
    setErro("");
    try {
      await sbRequest(`faturamento?id=eq.${id}`, session, { method: "DELETE" });
      setRegistros((rs) => rs.filter((r) => r.id !== id));
    } catch (e) { setErro(e.message); }
  }

  async function handleNovoManual() {
    setSalvando(true);
    setErro("");
    try {
      const body = {
        cliente_id: form.clienteId || null, orcamento_id: null, valor: form.valor,
        data_faturamento: form.dataFaturamento || null,
        mes_ref: form.dataFaturamento ? `${form.dataFaturamento.slice(0, 7)}-01` : `${mesRef}-01`,
      };
      await sbRequest("faturamento", session, { method: "POST", body });
      setShowForm(false);
      setForm(blankForm);
      carregar();
    } catch (e) { setErro(e.message); }
    finally { setSalvando(false); }
  }

  const total = registros.reduce((s, r) => s + r.valor, 0);

  return (
    <div>
      <div style={{ display: "flex", gap: 12, marginBottom: 18, flexWrap: "wrap", alignItems: "center", justifyContent: "space-between" }}>
        <MesPicker mesRef={mesRef} setMesRef={setMesRef} />
        <button onClick={() => { setForm(blankForm); setShowForm(true); }} style={btnPrimary}><Plus size={16} /> Lançamento manual</button>
      </div>

      {showForm && (
        <Card style={{ marginBottom: 18 }}>
          <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 12 }}>
            <h4 style={{ margin: 0, fontSize: 14 }}>Novo lançamento de faturamento</h4>
            <button onClick={() => setShowForm(false)} style={{ background: "none", border: "none", cursor: "pointer", color: MUTED }}><X size={18} /></button>
          </div>
          <div style={{ display: "grid", gridTemplateColumns: "2fr 1fr 1fr", gap: 12 }}>
            <Field label="Cliente">
              <select style={inputStyle} value={form.clienteId} onChange={(e) => setForm({ ...form, clienteId: e.target.value })}>
                <option value="">Selecione...</option>
                {clientes.map((c) => <option key={c.id} value={c.id}>{c.nome}</option>)}
              </select>
            </Field>
            <Field label="Valor (R$)"><input type="number" step="0.01" style={inputStyle} value={form.valor} onChange={(e) => setForm({ ...form, valor: parseFloat(e.target.value) || 0 })} /></Field>
            <Field label="Data"><input type="date" style={inputStyle} value={form.dataFaturamento} onChange={(e) => setForm({ ...form, dataFaturamento: e.target.value })} /></Field>
          </div>
          <div style={{ display: "flex", justifyContent: "flex-end", gap: 8, marginTop: 16 }}>
            <button onClick={() => setShowForm(false)} style={btnGhostSmall}>Cancelar</button>
            <button onClick={handleNovoManual} disabled={salvando} style={btnPrimary}><Save size={15} /> {salvando ? "Salvando..." : "Salvar"}</button>
          </div>
        </Card>
      )}

      <Card style={{ padding: 0, overflow: "hidden" }}>
        <div style={{ overflowX: "auto" }}>
          <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 13 }}>
            <thead>
              <tr style={{ background: "#F0F2F6", textAlign: "left" }}>
                {["Data", "Cliente", "Origem", "Valor", ""].map((h) => (
                  <th key={h} style={{ padding: "10px 14px", fontWeight: 600, color: MUTED, fontSize: 11, textTransform: "uppercase", letterSpacing: 0.4 }}>{h}</th>
                ))}
              </tr>
            </thead>
            <tbody>
              {carregando ? (
                <tr><td colSpan={5} style={{ padding: 20, color: MUTED, textAlign: "center" }}>Carregando...</td></tr>
              ) : registros.length === 0 ? (
                <tr><td colSpan={5} style={{ padding: 20, color: MUTED, textAlign: "center" }}>Nenhum faturamento nesse mês.</td></tr>
              ) : registros.map((r) => (
                <tr key={r.id} style={{ borderTop: `1px solid ${BORDER}` }}>
                  <td style={{ padding: "8px 14px" }}>
                    <input type="date" style={{ ...inputStyle, fontSize: 12 }} defaultValue={r.dataFaturamento || ""} onBlur={(e) => { if (e.target.value !== (r.dataFaturamento || "")) handleSalvarData(r, e.target.value); }} />
                  </td>
                  <td style={{ padding: "8px 14px" }}>{r.clienteNome || "-"}</td>
                  <td style={{ padding: "8px 14px", color: MUTED, fontSize: 12 }}>{r.orcamentoEvento || "Lançamento manual"}</td>
                  <td style={{ padding: "8px 14px" }}>
                    <input
                      type="number" step="0.01" style={{ ...inputStyle, width: 120, fontFamily: FONT_MONO }}
                      defaultValue={r.valor}
                      onBlur={(e) => { const v = parseFloat(e.target.value) || 0; if (v !== r.valor) handleSalvarValor(r, v); }}
                    />
                  </td>
                  <td style={{ padding: "8px 14px", textAlign: "right" }}>
                    <button onClick={() => handleExcluir(r.id)} style={btnDangerSmall}><Trash2 size={13} /></button>
                  </td>
                </tr>
              ))}
            </tbody>
            {registros.length > 0 && (
              <tfoot>
                <tr style={{ borderTop: `2px solid ${BORDER}` }}>
                  <td colSpan={3} style={{ padding: "10px 14px", fontWeight: 700 }}>Total do mês</td>
                  <td style={{ padding: "10px 14px", fontFamily: FONT_MONO, fontWeight: 700 }}>{brl(total)}</td>
                  <td></td>
                </tr>
              </tfoot>
            )}
          </table>
        </div>
      </Card>
    </div>
  );
}

// =========================================================
// Comercial · Dashboard
// =========================================================
function DashboardComercialView({ session, setErro, clientes }) {
  const [mesRef, setMesRef] = useState(() => {
    const d = new Date();
    return `${d.getFullYear()}-${MESES[d.getMonth()]}`;
  });
  const [carregando, setCarregando] = useState(false);
  const [orcMes, setOrcMes] = useState([]);
  const [faturadoMes, setFaturadoMes] = useState(0);
  const [vendidoMesAnoAnterior, setVendidoMesAnoAnterior] = useState(0);
  const [acumuladoAno, setAcumuladoAno] = useState([]);

  useEffect(() => {
    const [ano, mes] = mesRef.split("-").map(Number);
    const anoAnterior = ano - 1;
    const inicioAno = `${ano}-01-01`;
    setCarregando(true);
    setErro("");
    Promise.all([
      sbRequest(`orcamentos?select=*,clientes(nome)&mes_ref=eq.${mesRef}-01`, session),
      sbRequest(`faturamento?select=valor&mes_ref=eq.${mesRef}-01`, session),
      sbRequest(`orcamentos?select=valor&status=eq.aprovado&mes_ref=eq.${anoAnterior}-${MESES[mes - 1]}-01`, session),
      sbRequest(`orcamentos?select=valor,clientes(nome)&status=eq.aprovado&mes_ref=gte.${inicioAno}&mes_ref=lte.${mesRef}-01`, session),
    ])
      .then(([oMes, fMes, oAnoAnt, oAcum]) => {
        setOrcMes((oMes || []).map(orcamentoFromRow));
        setFaturadoMes((fMes || []).reduce((s, r) => s + Number(r.valor || 0), 0));
        setVendidoMesAnoAnterior((oAnoAnt || []).reduce((s, r) => s + Number(r.valor || 0), 0));
        setAcumuladoAno((oAcum || []).map((r) => ({ valor: Number(r.valor || 0), clienteNome: r.clientes?.nome || "Sem cliente" })));
      })
      .catch((e) => setErro(e.message))
      .finally(() => setCarregando(false));
  }, [mesRef]); // eslint-disable-line

  const vendidoMes = orcMes.filter((o) => o.status === "aprovado").reduce((s, o) => s + o.valor, 0);
  const variacao = vendidoMesAnoAnterior > 0 ? (vendidoMes - vendidoMesAnoAnterior) / vendidoMesAnoAnterior : null;

  const porStatus = STATUS_ORCAMENTO.map((s) => {
    const itens = orcMes.filter((o) => o.status === s.id);
    return { ...s, count: itens.length, soma: itens.reduce((acc, o) => acc + o.valor, 0) };
  });

  function agruparPorCliente(lista) {
    const mapa = {};
    lista.forEach((item) => {
      const nome = item.clienteNome || "Sem cliente";
      mapa[nome] = (mapa[nome] || 0) + item.valor;
    });
    return Object.entries(mapa).sort((a, b) => b[1] - a[1]);
  }

  const vendasPorClienteMes = agruparPorCliente(orcMes.filter((o) => o.status === "aprovado").map((o) => ({ clienteNome: o.clienteNome, valor: o.valor })));
  const vendasPorClienteAcumulado = agruparPorCliente(acumuladoAno);

  return (
    <div>
      <div style={{ marginBottom: 18 }}>
        <MesPicker mesRef={mesRef} setMesRef={setMesRef} />
      </div>

      {carregando ? (
        <div style={{ color: MUTED, fontSize: 13 }}>Carregando...</div>
      ) : (
        <>
          <div style={{ display: "grid", gridTemplateColumns: "repeat(3, 1fr)", gap: 14, marginBottom: 18 }}>
            <SummaryCard label="Vendido no mês (resultado)" value={brl(vendidoMes)} color={GOLD} dark />
            <SummaryCard label="Faturado no mês" value={brl(faturadoMes)} color={OK} />
            <SummaryCard
              label={`Vs. mesmo mês ano anterior (${brl(vendidoMesAnoAnterior)})`}
              value={variacao === null ? "-" : `${variacao >= 0 ? "+" : ""}${(variacao * 100).toFixed(1)}%`}
              color={variacao === null ? MUTED : variacao >= 0 ? OK : DANGER}
            />
          </div>

          <h3 style={{ fontSize: 15, fontWeight: 700, marginBottom: 10 }}>Orçamentos do mês por status</h3>
          <div style={{ display: "grid", gridTemplateColumns: "repeat(4, 1fr)", gap: 14, marginBottom: 24 }}>
            {porStatus.map((s) => (
              <Card key={s.id}>
                <div style={{ fontSize: 11, color: MUTED, textTransform: "uppercase", letterSpacing: 0.5 }}>{s.label}</div>
                <div style={{ fontSize: 20, fontWeight: 700, fontFamily: FONT_MONO, color: s.color, marginTop: 4 }}>{s.count}</div>
                <div style={{ fontSize: 12, color: MUTED, fontFamily: FONT_MONO, marginTop: 2 }}>{brl(s.soma)}</div>
              </Card>
            ))}
          </div>

          <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 18 }}>
            <div>
              <h3 style={{ fontSize: 15, fontWeight: 700, marginBottom: 10 }}>Vendas por cliente (mês)</h3>
              <Card style={{ padding: 0, overflow: "hidden" }}>
                <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 13 }}>
                  <tbody>
                    {vendasPorClienteMes.length === 0 ? (
                      <tr><td style={{ padding: 16, color: MUTED, textAlign: "center" }}>Sem vendas aprovadas no mês.</td></tr>
                    ) : vendasPorClienteMes.map(([nome, valor]) => (
                      <tr key={nome} style={{ borderTop: `1px solid ${BORDER}` }}>
                        <td style={{ padding: "8px 14px" }}>{nome}</td>
                        <td style={{ padding: "8px 14px", fontFamily: FONT_MONO, textAlign: "right" }}>{brl(valor)}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </Card>
            </div>
            <div>
              <h3 style={{ fontSize: 15, fontWeight: 700, marginBottom: 10 }}>Vendas por cliente (acumulado no ano)</h3>
              <Card style={{ padding: 0, overflow: "hidden" }}>
                <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 13 }}>
                  <tbody>
                    {vendasPorClienteAcumulado.length === 0 ? (
                      <tr><td style={{ padding: 16, color: MUTED, textAlign: "center" }}>Sem dados.</td></tr>
                    ) : vendasPorClienteAcumulado.map(([nome, valor]) => (
                      <tr key={nome} style={{ borderTop: `1px solid ${BORDER}` }}>
                        <td style={{ padding: "8px 14px" }}>{nome}</td>
                        <td style={{ padding: "8px 14px", fontFamily: FONT_MONO, textAlign: "right" }}>{brl(valor)}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </Card>
            </div>
          </div>
        </>
      )}
    </div>
  );
}

function SummaryCard({ label, value, color, dark }) {
  return (
    <Card style={dark ? { background: NAVY_DARK, color: "#fff" } : {}}>
      <div style={{ fontSize: 11, color: dark ? "#9FB0CC" : MUTED, textTransform: "uppercase", letterSpacing: 0.5 }}>{label}</div>
      <div style={{ fontSize: 24, fontWeight: 700, fontFamily: FONT_MONO, color, marginTop: 4 }}>{value}</div>
    </Card>
  );
}

const BAR_COLORS = { he50: "#8FA6C9", he60: "#5D7FAE", he100: "#2F4E7D", adicNot: "#B8902E", heNot50: "#C79A4B", heNot60: "#A6394A", heNot100: "#6B2530" };
function StackedBar({ linhas }) {
  const total = linhas.reduce((s, l) => s + (l.soAdicional ? 0 : l.dentro), 0);
  if (total === 0) return <div style={{ fontSize: 11, color: MUTED }}>—</div>;
  return (
    <div style={{ display: "flex", height: 10, borderRadius: 4, overflow: "hidden", width: "100%" }} title="Distribuição de horas extras (até 40h)">
      {linhas.filter((l) => !l.soAdicional && l.dentro > 0).map((l) => (
        <div key={l.key} style={{ width: `${(l.dentro / total) * 100}%`, background: BAR_COLORS[l.key] }} />
      ))}
    </div>
  );
}
